// ---- Iroh consumer surface (Phases A2 → D2) --------------------------------
//
// Exposes the shared `IrohBackedResolver` and the JSON-RPC-over-iroh ALPNs
// to RPC clients that want to use the QUIC + Pkarr + iroh-blobs substrate
// directly (without going through HTTPS). Internal subsystems
// (`IrohBlobsDaBackend`, `IrohGradientStore`, `IrohSealedShardStore`,
// memory-archive DA, A2A-over-iroh) consume the same resolver — see
// `crates/tenzro-iroh/src/lib.rs` rustdoc.
//
// The iroh data plane is always bound at startup. The only case in which
// `iroh_resolver` is `None` is when the initial bind failed (e.g. local
// UDP socket conflict, OS-level transport error). Clients receive `-32004`
// "iroh transport not bound" so the failure is distinguishable from a
// transient request-level error.

fn iroh_resolver_or_err(
    node: &Arc<TenzroNode>,
) -> std::result::Result<Arc<tenzro_iroh::IrohBackedResolver>, JsonRpcError> {
    node.iroh_resolver.clone().ok_or_else(|| JsonRpcError {
        code: -32004,
        message: "iroh transport not bound on this node".to_string(),
        data: Some(serde_json::json!({
            "hint": "iroh failed to bind at startup; check node logs for the bind error"
        })),
    })
}

async fn handle_iroh_get_endpoint_id(
    node: &Arc<TenzroNode>,
) -> std::result::Result<Value, JsonRpcError> {
    let resolver = iroh_resolver_or_err(node)?;
    let id = resolver.endpoint().id();
    // EndpointId Display = z-base-32 (n0 canonical); to_string() yields the
    // same form printed by `iroh node id`. Hex-encoded raw bytes are also
    // returned so callers that want the byte-identical TDIP key can use it.
    let id_str = id.to_string();
    let id_hex = hex::encode(id.as_bytes());
    Ok(serde_json::json!({
        "endpoint_id": id_str,
        "endpoint_id_hex": id_hex,
    }))
}

async fn handle_iroh_list_alpns(
    node: &Arc<TenzroNode>,
) -> std::result::Result<Value, JsonRpcError> {
    let _ = iroh_resolver_or_err(node)?;
    // The shared router binds three ALPNs at startup (see
    // `init_ai_infrastructure`): iroh-blobs (data plane), and the two
    // JSON-RPC ALPNs (A2A always; MCP follow-up). Report A2A as bound
    // iff the deferred dispatcher slot exists on the node.
    let mut alpns = vec![
        serde_json::json!({
            "alpn": "iroh-blobs",
            "description": "iroh-blobs BLAKE3 content-addressed transport",
        }),
    ];
    if node.iroh_a2a_dispatcher.is_some() {
        alpns.push(serde_json::json!({
            "alpn": String::from_utf8_lossy(tenzro_iroh::ALPN_A2A).to_string(),
            "description": "A2A JSON-RPC 2.0 over iroh (mirrors POST /a2a)",
        }));
    }
    Ok(serde_json::json!({ "alpns": alpns }))
}

async fn handle_iroh_get_info(
    node: &Arc<TenzroNode>,
) -> std::result::Result<Value, JsonRpcError> {
    let resolver = iroh_resolver_or_err(node)?;
    let id = resolver.endpoint().id();
    let cfg = &node.config().iroh;
    let pkarr_relay = cfg.pkarr_relay_url.as_ref().map(|u| u.to_string());
    let mut alpns = vec!["iroh-blobs"];
    if node.iroh_a2a_dispatcher.is_some() {
        alpns.push("tenzro/a2a");
    }
    Ok(serde_json::json!({
        "endpoint_id": id.to_string(),
        "endpoint_id_hex": hex::encode(id.as_bytes()),
        "pkarr_relay_url": pkarr_relay,
        "publish_to_n0_default_discovery": cfg.publish_to_n0_default_discovery,
        "docs_enabled": cfg.enable_docs,
        "bound_alpns": alpns,
    }))
}

async fn handle_iroh_publish_blob(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    use base64::Engine as _;
    use tenzro_iroh::IrohResolver as _;
    let resolver = iroh_resolver_or_err(node)?;
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let bytes_b64 = params
        .get("bytes_b64")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing bytes_b64 (base64-encoded payload)".to_string(),
            data: None,
        })?;
    let bytes = base64::engine::general_purpose::STANDARD
        .decode(bytes_b64)
        .map_err(|e| JsonRpcError {
            code: -32602,
            message: format!("bytes_b64 not valid base64: {e}"),
            data: None,
        })?;
    let size = bytes.len();
    let uri = resolver
        .publish_bytes(bytes::Bytes::from(bytes))
        .await
        .map_err(|e| JsonRpcError {
            code: -32000,
            message: format!("iroh publish_bytes: {e}"),
            data: None,
        })?;
    Ok(serde_json::json!({
        "tenzro_uri": uri.to_string(),
        "size_bytes": size,
    }))
}

async fn handle_iroh_fetch_blob(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    use base64::Engine as _;
    use tenzro_iroh::IrohResolver as _;
    let resolver = iroh_resolver_or_err(node)?;
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let uri_str = params
        .get("tenzro_uri")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing tenzro_uri (e.g. tenzro://blob/<hash>)".to_string(),
            data: None,
        })?;
    let uri = tenzro_types::tenzro_uri::TenzroUri::parse(uri_str).map_err(|e| JsonRpcError {
        code: -32602,
        message: format!("parse tenzro_uri: {e}"),
        data: None,
    })?;
    let bytes = resolver
        .fetch_bytes(&uri)
        .await
        .map_err(|e| JsonRpcError {
            code: -32000,
            message: format!("iroh fetch_bytes: {e}"),
            data: None,
        })?;
    let b64 = base64::engine::general_purpose::STANDARD.encode(&bytes);
    Ok(serde_json::json!({
        "tenzro_uri": uri.to_string(),
        "size_bytes": bytes.len(),
        "bytes_b64": b64,
    }))
}

/// Generic dispatcher for any content-addressed `tenzro://` URI. Dispatches
/// `tenzro://memory/<did>/<uuid>` through [`MemoryManager`] (point-lookup; if
/// archived, follow the `DaPointer` to fetch the bulk payload from DA); falls
/// back to the iroh resolver's `fetch_blob` path for every other variant.
async fn handle_iroh_resolve_tenzro_uri(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    use base64::Engine as _;
    let uri_str: String = {
        let params_ref = params.as_ref().ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing params".to_string(),
            data: None,
        })?;
        params_ref
            .get("tenzro_uri")
            .and_then(|v| v.as_str())
            .ok_or_else(|| JsonRpcError {
                code: -32602,
                message: "Missing tenzro_uri".to_string(),
                data: None,
            })?
            .to_string()
    };
    let uri = tenzro_types::tenzro_uri::TenzroUri::parse(&uri_str).map_err(|e| JsonRpcError {
        code: -32602,
        message: format!("parse tenzro_uri: {e}"),
        data: None,
    })?;

    if let tenzro_types::tenzro_uri::TenzroUri::Memory { agent_did, record_uuid } = &uri {
        let mgr = require_memory_manager(node)?;
        let record = mgr.get_by_id(agent_did, record_uuid).map_err(|e| JsonRpcError {
            code: -32000,
            message: format!("memory get_by_id: {e}"),
            data: None,
        })?;
        let record = record.ok_or_else(|| JsonRpcError {
            code: -32004,
            message: format!("memory record {}/{} not found", agent_did, record_uuid),
            data: None,
        })?;
        // Archived records fan out to the DA backend; hot records serialize
        // the on-tier row as the canonical payload (same shape as what
        // `archive()` originally submitted).
        let bytes = if record.kind == tenzro_agent::memory::MemoryKind::Archived
            && record.da_pointer.is_some()
        {
            mgr.fetch_archived(&record).await.map_err(|e| JsonRpcError {
                code: -32000,
                message: format!("memory fetch_archived: {e}"),
                data: None,
            })?
        } else {
            serde_json::to_vec(&record).map_err(|e| JsonRpcError {
                code: -32603,
                message: format!("serialize memory record: {e}"),
                data: None,
            })?
        };
        let b64 = base64::engine::general_purpose::STANDARD.encode(&bytes);
        return Ok(serde_json::json!({
            "tenzro_uri": uri.to_string(),
            "size_bytes": bytes.len(),
            "bytes_b64": b64,
        }));
    }

    handle_iroh_fetch_blob(node, params).await
}

// ---- Workflow read RPCs (Canton-native workflow stack) ---------------------
//
// All workflow / obligation / approval / privacy-domain *writes* are handled
// by the privileged-VM workflow selectors (`0x01000040`–`0x0100004B`)
// dispatched via `tenzro_signAndSendTransaction`. The post-block scan in
// `EventLoop::process_workflow_logs` mirrors the emitted typed logs into
// the in-memory `WorkflowRuntime`. These RPCs read from that runtime, which
// is itself rehydrated from RocksDB (CF_SETTLEMENTS + CF_APPROVALS) on
// startup.

/// Parse a 32-byte Hash from a hex string (with or without `0x` prefix).
fn parse_workflow_hash_param(
    s: &str,
    field: &str,
) -> std::result::Result<tenzro_types::primitives::Hash, JsonRpcError> {
    let stripped = s.strip_prefix("0x").unwrap_or(s);
    let bytes = hex::decode(stripped).map_err(|e| JsonRpcError {
        code: -32602,
        message: format!("Invalid {} hex: {}", field, e),
        data: None,
    })?;
    tenzro_types::primitives::Hash::from_bytes(&bytes).ok_or_else(|| JsonRpcError {
        code: -32602,
        message: format!("{} must be 32 bytes", field),
        data: None,
    })
}

fn workflow_runtime_or_err(
    node: &Arc<TenzroNode>,
) -> std::result::Result<Arc<crate::workflow_runtime::WorkflowRuntime>, JsonRpcError> {
    node.workflow_runtime()
        .cloned()
        .ok_or_else(|| JsonRpcError {
            code: -32000,
            message: "Workflow runtime not initialized".to_string(),
            data: None,
        })
}

fn workflow_status_from_str(
    s: &str,
) -> std::result::Result<tenzro_workflow::workflow::WorkflowStatus, JsonRpcError> {
    use tenzro_workflow::workflow::WorkflowStatus;
    Ok(match s {
        "draft" => WorkflowStatus::Draft,
        "awaiting_signatures" => WorkflowStatus::AwaitingSignatures,
        "active" => WorkflowStatus::Active,
        "suspended" => WorkflowStatus::Suspended,
        "settling" => WorkflowStatus::Settling,
        "completed" => WorkflowStatus::Completed,
        "failed" => WorkflowStatus::Failed,
        "disputed" => WorkflowStatus::Disputed,
        "cancelled" => WorkflowStatus::Cancelled,
        other => {
            return Err(JsonRpcError {
                code: -32602,
                message: format!("Unknown workflow status: {}", other),
                data: None,
            });
        }
    })
}

fn ids_to_hex_array(ids: Vec<tenzro_types::primitives::Hash>) -> Vec<String> {
    ids.iter()
        .map(|h| format!("0x{}", hex::encode(h.as_bytes())))
        .collect()
}

/// `tenzro_getWorkflow` — fetch a workflow by id.
async fn handle_get_workflow(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let p = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let wf_id_hex = p.get("workflow_id").and_then(|v| v.as_str()).ok_or_else(|| {
        JsonRpcError {
            code: -32602,
            message: "Missing workflow_id".to_string(),
            data: None,
        }
    })?;
    let wf_id = parse_workflow_hash_param(wf_id_hex, "workflow_id")?;
    let rt = workflow_runtime_or_err(node)?;
    match rt.manager().get_workflow(&wf_id) {
        Some(wf) => serde_json::to_value(&wf).map_err(|e| JsonRpcError {
            code: -32603,
            message: format!("workflow serialize: {}", e),
            data: None,
        }),
        None => Ok(Value::Null),
    }
}

/// `tenzro_listWorkflowsByCreator` — list workflow ids created by a DID.
async fn handle_list_workflows_by_creator(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let p = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let creator = p
        .get("creator_did")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing creator_did".to_string(),
            data: None,
        })?;
    let rt = workflow_runtime_or_err(node)?;
    let ids = rt.manager().list_by_creator(creator);
    Ok(serde_json::json!({
        "creator_did": creator,
        "count": ids.len(),
        "workflow_ids": ids_to_hex_array(ids),
    }))
}

