/// `tenzro_slaIssueProbe` — validator-side: produce a VRF-stamped probe for
/// `provider_did`, register it in the outstanding-probe correlator, and
/// broadcast it over the `tenzro/sla` gossipsub topic. The provider's
/// `SlaResponse` flows back through the same topic and the inbound subscriber
/// drives `SlaManager::apply_response` automatically.
///
/// Params: `{ "provider_did": "...", "epoch": <u64>, "round": <u64>,
///            "deadline_ms": <i64> }`.
async fn handle_sla_issue_probe(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let params = if let Some(arr) = params.as_array() {
        arr.first().cloned().unwrap_or(params)
    } else {
        params
    };

    let provider_did = params
        .get("provider_did")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing provider_did".to_string(),
            data: None,
        })?;
    let epoch = params
        .get("epoch")
        .and_then(|v| v.as_u64())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing epoch (u64)".to_string(),
            data: None,
        })?;
    let round = params
        .get("round")
        .and_then(|v| v.as_u64())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing round (u64)".to_string(),
            data: None,
        })?;
    let deadline_ms = params
        .get("deadline_ms")
        .and_then(|v| v.as_i64())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing deadline_ms (i64)".to_string(),
            data: None,
        })?;

    let manager = node.sla_manager().ok_or_else(|| JsonRpcError {
        code: -32000,
        message: "SlaManager not initialized (validator-only)".to_string(),
        data: None,
    })?;

    let probe = manager
        .issue_probe(provider_did, epoch, round, deadline_ms)
        .map_err(|e| JsonRpcError {
            code: -32000,
            message: format!("issue_probe failed: {}", e),
            data: None,
        })?;

    // Register the probe BEFORE broadcasting so a fast response cannot race
    // the insertion. Hex-encode the 32-byte nonce as the DashMap key.
    let nonce_hex = hex::encode(probe.challenge_nonce);
    node.sla_outstanding_probes()
        .insert(nonce_hex.clone(), probe.clone());

    // Broadcast over `tenzro/sla` if the network is up. ModelProvider /
    // TeeProvider nodes subscribed to the same topic will surface the probe
    // to their local provider runtime via the gossipsub receiver.
    if let Some(network) = node.network() {
        let payload = bincode::serialize(&probe).map_err(|e| JsonRpcError {
            code: -32000,
            message: format!("bincode serialize SlaProbe: {}", e),
            data: None,
        })?;
        let msg = tenzro_network::NetworkMessage::new(
            tenzro_network::MessagePayload::Custom {
                topic: "tenzro/sla".to_string(),
                data: payload,
            },
        );
        if let Err(e) = network.broadcast("tenzro/sla", msg).await {
            tracing::warn!(error = %e, "Failed to broadcast SLA probe on tenzro/sla");
        }
    }

    Ok(serde_json::json!({
        "issuer": format!("0x{}", hex::encode(probe.issuer.to_bytes())),
        "provider_did": probe.provider_did,
        "epoch": probe.epoch,
        "round": probe.round,
        "challenge_nonce": format!("0x{}", nonce_hex),
        "deadline_ms": probe.deadline_ms,
        "vrf_pubkey": format!("0x{}", hex::encode(probe.vrf_pubkey)),
    }))
}

/// `tenzro_slaListOutstandingProbes` — read-only reflector for in-flight
/// probes awaiting a provider response. Operators consult this to spot
/// stuck probes (deadline already passed but no response observed).
async fn handle_sla_list_outstanding_probes(
    node: &Arc<TenzroNode>,
) -> std::result::Result<Value, JsonRpcError> {
    let probes = node.sla_outstanding_probes();
    let entries: Vec<Value> = probes
        .iter()
        .map(|kv| {
            let p = kv.value();
            serde_json::json!({
                "challenge_nonce": format!("0x{}", kv.key()),
                "provider_did": p.provider_did,
                "epoch": p.epoch,
                "round": p.round,
                "deadline_ms": p.deadline_ms,
                "issuer": format!("0x{}", hex::encode(p.issuer.to_bytes())),
            })
        })
        .collect();
    Ok(serde_json::json!({
        "count": entries.len(),
        "probes": entries,
    }))
}

/// `tenzro_slaGetParams` — surface the configured fault-detector parameters
/// (slash threshold, slash amount per crossing, validator's VRF public key).
async fn handle_sla_get_params(
    node: &Arc<TenzroNode>,
) -> std::result::Result<Value, JsonRpcError> {
    let manager = node.sla_manager().ok_or_else(|| JsonRpcError {
        code: -32000,
        message: "SlaManager not initialized (validator-only)".to_string(),
        data: None,
    })?;
    Ok(serde_json::json!({
        "slash_threshold": manager.slash_threshold(),
        "slash_amount_wei": manager.slash_amount().to_string(),
        "vrf_pubkey": format!("0x{}", hex::encode(manager.vrf_public_key().0)),
    }))
}

/// `tenzro_increaseComputeBond` — top up an Active compute bond.
///
/// Params: `{ "provider_did": "...", "amount": "..." }`.
async fn handle_increase_compute_bond(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let params = if let Some(arr) = params.as_array() {
        arr.first().cloned().unwrap_or(params)
    } else {
        params
    };

    let provider_did = params
        .get("provider_did")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing provider_did".to_string(),
            data: None,
        })?;
    let amount = parse_u128_amount(&params, "amount").ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing or invalid amount (wei)".to_string(),
        data: None,
    })?;

    let manager = node
        .compute_bond_manager()
        .ok_or_else(|| JsonRpcError {
            code: -32000,
            message: "ComputeBondManager not initialized".to_string(),
            data: None,
        })?
        .clone();

    let block_height = node.chain_tip_height();
    let state = manager
        .increase(provider_did, amount, block_height)
        .map_err(|e| JsonRpcError {
            code: -32000,
            message: format!("increase compute bond failed: {}", e),
            data: None,
        })?;

    Ok(compute_bond_state_to_json(&state))
}

/// `tenzro_withdrawComputeBond` — initiate withdrawal on an Active bond.
/// Bond enters 7-day cooldown; finalize via `finalize_withdrawal` once
/// cooldown elapses (currently triggered by a follow-up call to this RPC
/// after the cooldown timer is past).
///
/// Params: `{ "provider_did": "..." }`.
async fn handle_withdraw_compute_bond(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let params = if let Some(arr) = params.as_array() {
        arr.first().cloned().unwrap_or(params)
    } else {
        params
    };

    let provider_did = params
        .get("provider_did")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing provider_did".to_string(),
            data: None,
        })?;

    let manager = node
        .compute_bond_manager()
        .ok_or_else(|| JsonRpcError {
            code: -32000,
            message: "ComputeBondManager not initialized".to_string(),
            data: None,
        })?
        .clone();

    let block_height = node.chain_tip_height();

    // If the bond is already in Cooldown and the timer has elapsed,
    // promote to Returned in this same call. Otherwise, kick off the
    // Active → Cooldown transition.
    let existing = manager.get(provider_did);
    let state = match existing {
        Some(s) if matches!(s.status, tenzro_token::compute_bond::ComputeBondStatus::Cooldown) => {
            manager
                .finalize_withdrawal(provider_did, block_height)
                .map_err(|e| JsonRpcError {
                    code: -32000,
                    message: format!("finalize compute bond withdrawal failed: {}", e),
                    data: None,
                })?
        }
        _ => manager
            .withdraw(provider_did, block_height)
            .map_err(|e| JsonRpcError {
                code: -32000,
                message: format!("withdraw compute bond failed: {}", e),
                data: None,
            })?,
    };

    Ok(compute_bond_state_to_json(&state))
}

/// Render a `ValidatorRegistryEntry` as JSON (consumed by all three read RPCs).
fn validator_registry_entry_to_json(
    entry: &tenzro_token::validator_registry::ValidatorRegistryEntry,
) -> Value {
    serde_json::json!({
        "address": format!("{}", entry.address),
        "consensus_pubkey": hex::encode(&entry.consensus_pubkey),
        "pq_pubkey_len": entry.pq_pubkey.len(),
        "bls_pubkey": hex::encode(&entry.bls_pubkey),
        "withdrawal_address": format!("{}", entry.withdrawal_address),
        "self_stake": entry.self_stake.to_string(),
        "status": format!("{:?}", entry.status),
        "registered_at_epoch": entry.registered_at_epoch,
        "activated_at_epoch": entry.activated_at_epoch,
        "exited_at_epoch": entry.exited_at_epoch,
        "jailed_until_epoch": entry.jailed_until_epoch,
        "tee_attestation_hash": entry.tee_attestation_hash.map(hex::encode),
        "metadata_uri": entry.metadata_uri,
        "updated_at": entry.updated_at.0,
    })
}

/// `tenzro_getValidatorState` — fetch a single validator's registry entry by
/// address. Returns `null` if the address is not registered.
///
/// Params: `{ "address": "0x..." }` (32-byte hex, with or without `0x`).
async fn handle_get_validator_state(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let address_str = params
        .get("address")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing address".to_string(),
            data: None,
        })?;
    let cleaned = address_str.trim_start_matches("0x");
    let bytes = hex::decode(cleaned).map_err(|e| JsonRpcError {
        code: -32602,
        message: format!("Invalid hex address: {}", e),
        data: None,
    })?;
    let address = tenzro_types::primitives::Address::from_bytes(&bytes)
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Address must be 32 bytes".to_string(),
            data: None,
        })?;

    let registry = node.validator_registry().ok_or_else(|| JsonRpcError {
        code: -32000,
        message: "ValidatorRegistry not initialized".to_string(),
        data: None,
    })?;
    match registry.get(&address) {
        Some(entry) => Ok(validator_registry_entry_to_json(&entry)),
        None => Ok(Value::Null),
    }
}

/// `tenzro_listValidators` — list all validators in the registry, optionally
/// filtered by status.
///
/// Params (optional): `{ "status": "Active" | "Candidate" | "PendingActive" |
///                                  "PendingExit" | "Exited" | "Jailed" }`.
async fn handle_list_validators(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let registry = node.validator_registry().ok_or_else(|| JsonRpcError {
        code: -32000,
        message: "ValidatorRegistry not initialized".to_string(),
        data: None,
    })?;

    let status_filter: Option<String> = params
        .as_ref()
        .and_then(|p| p.get("status"))
        .and_then(|v| v.as_str())
        .map(|s| s.to_string());

    let entries = registry.list();
    let filtered: Vec<_> = if let Some(want) = &status_filter {
        entries
            .into_iter()
            .filter(|e| format!("{:?}", e.status) == *want)
            .collect()
    } else {
        entries
    };

    Ok(serde_json::json!({
        "count": filtered.len(),
        "validators": filtered.iter().map(validator_registry_entry_to_json).collect::<Vec<_>>(),
    }))
}

/// `tenzro_listActiveValidators` — list only the currently `Active`
/// validators. Convenience over `tenzro_listValidators` with
/// `{ "status": "Active" }`.
async fn handle_list_active_validators(
    node: &Arc<TenzroNode>,
) -> std::result::Result<Value, JsonRpcError> {
    let registry = node.validator_registry().ok_or_else(|| JsonRpcError {
        code: -32000,
        message: "ValidatorRegistry not initialized".to_string(),
        data: None,
    })?;
    let actives = registry.list_active();
    Ok(serde_json::json!({
        "count": actives.len(),
        "validators": actives.iter().map(validator_registry_entry_to_json).collect::<Vec<_>>(),
    }))
}

/// `tenzro_getAccountContention` — read the rolling Block-STM contention
/// score for an account over the last 64 blocks (Agent-Swarm Spec 6).
///
/// Params: `{ "address": "0x..." }` (hex-encoded, with or without `0x` prefix).
///
/// Returns:
/// ```json
/// {
///   "address": "0x...",
///   "score": 0.42,                  // reexecutions / writes over the window
///   "reexecutions": 21,             // total Block-STM reexec count over window
///   "writes": 50,                   // total distinct address-write count
///   "is_hot": true,                 // both score >= 0.20 and writes >= 50
///   "multiplier": 2.10,             // local fee multiplier (1.0–5.0)
///   "base_fee_per_gas": "0x...",    // current EIP-1559 base fee (hex u128)
///   "effective_base_fee_per_gas": "0x...",  // base * multiplier
///   "surcharge_per_gas": "0x...",   // burn delta (effective - base)
///   "window_blocks": 64,
///   "score_floor": 0.20,
///   "write_floor": 50,
///   "max_multiplier": 5.0
/// }
/// ```
async fn handle_get_account_contention(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let address_str = params
        .get("address")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing address".to_string(),
            data: None,
        })?;
    let address_hex = address_str.strip_prefix("0x").unwrap_or(address_str);
    let address = hex::decode(address_hex).map_err(|e| JsonRpcError {
        code: -32602,
        message: format!("Invalid address hex: {}", e),
        data: None,
    })?;

    let vm_runtime = node.vm_runtime().ok_or_else(|| JsonRpcError {
        code: -32000,
        message: "VM runtime not initialized".to_string(),
        data: None,
    })?;
    let oracle = vm_runtime.gas_oracle();
    let score = oracle.hot_state().contention(&address);
    let multiplier = score.multiplier();
    let base_fee = oracle.current_price().await.base_fee;
    let (effective, surcharge) = oracle.hot_state().surcharge(&address, base_fee);

    Ok(serde_json::json!({
        "address": format!("0x{}", hex::encode(&address)),
        "score": score.score,
        "reexecutions": score.reexecutions,
        "writes": score.writes,
        "is_hot": score.is_hot,
        "multiplier": multiplier,
        "base_fee_per_gas": format!("0x{:x}", base_fee),
        "effective_base_fee_per_gas": format!("0x{:x}", effective),
        "surcharge_per_gas": format!("0x{:x}", surcharge),
        "window_blocks": tenzro_vm::HOT_STATE_WINDOW_BLOCKS,
        "score_floor": tenzro_vm::HOT_STATE_SCORE_FLOOR,
        "write_floor": tenzro_vm::HOT_STATE_WRITE_FLOOR,
        "max_multiplier": tenzro_vm::HOT_STATE_MAX_MULTIPLIER,
    }))
}

/// `tenzro_getBurnQuota` — read the singleton BurnQuota state
/// (Agent-Swarm Spec 3 — wave 1).
///
/// Params: none.
///
/// Returns:
/// ```json
/// {
///   "balance":         "0x...",   // TNZO available to sponsor (1e18 base units, hex)
///   "cap":             "0x...",
///   "daily_target":    "0x...",
///   "min_reserve_bps": 1000,       // basis points
///   "min_reserve":     "0x...",   // derived: cap × bps / 10_000
///   "last_refill":     1714824000, // ms timestamp
///   "total_drained":   "0x...",
///   "total_refilled":  "0x...",
///   "deficit":         0,          // signed; negative is impossible in wave 1
///   "can_drain_one":   true        // can_drain(1) — quick "is the quota live" hint
/// }
/// ```
///
/// In wave 1 the quota is read-only over RPC. Drains and refills happen
/// in-process via `BurnQuotaManager::try_drain` / `refill`, which the
/// future StablecoinPaymaster + QuotaReplenisher will invoke. There is
/// no write RPC for refills — that channel is privileged-VM only and
/// will be added when the replenisher lands.
async fn handle_get_burn_quota(
    node: &Arc<TenzroNode>,
) -> std::result::Result<Value, JsonRpcError> {
    let manager = node.burn_quota_manager().ok_or_else(|| JsonRpcError {
        code: -32000,
        message: "BurnQuotaManager not initialized".to_string(),
        data: None,
    })?;
    let s = manager.state();
    let min_reserve = s.min_reserve();
    let can_drain_one = s.can_drain(1);
    Ok(serde_json::json!({
        "balance": format!("0x{:x}", s.balance),
        "cap": format!("0x{:x}", s.cap),
        "daily_target": format!("0x{:x}", s.daily_target),
        "min_reserve_bps": s.min_reserve_bps,
        "min_reserve": format!("0x{:x}", min_reserve),
        "last_refill": s.last_refill,
        "total_drained": format!("0x{:x}", s.total_drained),
        "total_refilled": format!("0x{:x}", s.total_refilled),
        "deficit": s.deficit,
        "can_drain_one": can_drain_one,
    }))
}

/// `tenzro_getDaBackends` — list configured DA backends and their status
/// (Agent-Swarm Spec 7 — wave 1).
///
/// Params: none.
///
/// Returns: `[{ backend, healthy, last_submission_ms, last_fetch_ms,
/// error_rate_bps }]`. In wave 1 the only configured backend is
/// `inline_fallback`, which refuses offload — receipts must use
/// `storage_mode = Inline`. EigenDA / Celestia / Avail entries appear when
/// their feature-gated adapters land.
async fn handle_get_da_backends(
    _node: &Arc<TenzroNode>,
) -> std::result::Result<Value, JsonRpcError> {
    let backend = tenzro_storage::InlineFallbackBackend::new();
    let status = tenzro_storage::DaBackend::status(&backend);
    let entry = serde_json::json!({
        "backend": status.backend.as_str(),
        "healthy": status.healthy,
        "last_submission_ms": status.last_submission_ms,
        "last_fetch_ms": status.last_fetch_ms,
        "error_rate_bps": status.error_rate_bps,
    });
    Ok(serde_json::json!([entry]))
}

/// `tenzro_verifyDaPointer` — probe whether a DA pointer is dereferenceable
/// right now without paying the retrieval bandwidth (Agent-Swarm Spec 7 —
/// wave 1).
///
/// Params:
/// ```json
/// {
///   "pointer": {
///     "backend": "eigenda" | "celestia" | "avail" | "inline_fallback",
///     "namespace": "0x..",      // hex-encoded bytes
///     "locator":   "0x..",
///     "commitment_kzg":   "0x..",   // optional
///     "attestation_root": "0x.."   // optional, 32-byte hex
///   }
/// }
/// ```
///
/// Returns: `{ available: bool, backend: "...", reason: "..." }`. In wave 1
/// the only configured backend is `inline_fallback`, which always returns
/// `available: false` because it cannot dereference external pointers — the
/// real probes land alongside the EigenDA / Celestia / Avail adapters.
async fn handle_verify_da_pointer(
    _node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let pointer_val = params.get("pointer").ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing pointer".to_string(),
        data: None,
    })?;

    let backend_str = pointer_val
        .get("backend")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing pointer.backend".to_string(),
            data: None,
        })?;
    let backend = match backend_str {
        "inline_fallback" => tenzro_storage::DaBackendId::InlineFallback,
        "eigenda" => tenzro_storage::DaBackendId::EigenDA,
        "celestia" => tenzro_storage::DaBackendId::Celestia,
        "avail" => tenzro_storage::DaBackendId::Avail,
        other => {
            return Err(JsonRpcError {
                code: -32602,
                message: format!("Unknown DA backend: {}", other),
                data: None,
            });
        }
    };

    fn decode_hex_field(value: &str, field: &str) -> std::result::Result<Vec<u8>, JsonRpcError> {
        let stripped = value.strip_prefix("0x").unwrap_or(value);
        hex::decode(stripped).map_err(|e| JsonRpcError {
            code: -32602,
            message: format!("Invalid hex in pointer.{}: {}", field, e),
            data: None,
        })
    }

    let namespace = match pointer_val.get("namespace").and_then(|v| v.as_str()) {
        Some(s) => decode_hex_field(s, "namespace")?,
        None => Vec::new(),
    };
    let locator = match pointer_val.get("locator").and_then(|v| v.as_str()) {
        Some(s) => decode_hex_field(s, "locator")?,
        None => Vec::new(),
    };
    let commitment_kzg = match pointer_val.get("commitment_kzg").and_then(|v| v.as_str()) {
        Some(s) => Some(decode_hex_field(s, "commitment_kzg")?),
        None => None,
    };
    let attestation_root = match pointer_val.get("attestation_root").and_then(|v| v.as_str()) {
        Some(s) => {
            let bytes = decode_hex_field(s, "attestation_root")?;
            Some(Hash::from_bytes(&bytes).ok_or_else(|| JsonRpcError {
                code: -32602,
                message: "attestation_root must be 32 bytes".to_string(),
                data: None,
            })?)
        }
        None => None,
    };

    let pointer = tenzro_storage::DaPointer {
        backend,
        namespace,
        locator,
        commitment_kzg,
        attestation_root,
    };

    // Wave 1: only the inline-fallback backend is wired. Probes against any
    // external backend resolve to "not available" because the adapter is
    // not loaded — a clear signal to operators that they need to enable the
    // backend feature flag before relying on offload.
    let inline = tenzro_storage::InlineFallbackBackend::new();
    let result = tenzro_storage::DaBackend::verify_availability(&inline, &pointer).await;
    let (available, reason) = match result {
        Ok(()) => (true, String::new()),
        Err(e) => (false, e.to_string()),
    };
    Ok(serde_json::json!({
        "available": available,
        "backend": backend.as_str(),
        "reason": reason,
    }))
}

// ---- ERC-7683 cross-chain intent read RPCs (Agent-Swarm Spec 4) -------------

/// Render a `Tenzro7683Order` envelope as JSON for read-only RPC responses.
fn tenzro_7683_order_to_json(order: &tenzro_types::intent_7683::Tenzro7683Order) -> Value {
    serde_json::json!({
        "order_id": format!("0x{}", hex::encode(order.order_id.as_bytes())),
        "state": order.state.as_str(),
        "escrow_id": format!("0x{}", hex::encode(order.escrow_id.as_bytes())),
        "opened_at_ms": order.opened_at.as_millis(),
        "fill_deadline": order.fill_deadline,
        "filler": order.filler.as_ref().map(|a| format!("0x{}", hex::encode(a.as_bytes()))),
        "fill_proof_hash": order.fill_proof_hash.as_ref().map(|h| format!("0x{}", hex::encode(h.as_bytes()))),
        "proof_route": order.proof_route.as_str(),
        "resolved": order.resolved,
    })
}

/// `tenzro_open7683Order` — open a Tenzro-origin ERC-7683 cross-chain order.
///
/// Constructs a [`tenzro_types::intent_7683::Tenzro7683Order`] envelope in
/// [`tenzro_types::intent_7683::OrderState::Open`], persists it under the
/// `7683_origin:` keyspace in `CF_SETTLEMENTS`, and returns the canonical
/// 32-byte order id. Subsequent fills are recorded via the existing
/// `tenzro_recordFill7683` / `tenzro_getFill7683` surface; reads of the
/// envelope go through `tenzro_get7683Order` / `tenzro_list7683Orders`.
///
/// Params (all required):
/// - `settlement_contract`: 32-byte hex address of the settler contract.
/// - `swapper`: 32-byte hex address of the user opening the order.
/// - `nonce`: u64 monotonic nonce per swapper.
/// - `origin_chain_id`: u32 CAIP-2 numeric chain id of the order's origin.
/// - `fill_deadline`: u32 Unix-second deadline by which a fill must land.
/// - `order_data_type`: 32-byte hex Keccak-256 typehash of `order_data`.
/// - `order_data`: hex-encoded opaque payload (Tenzro orders encode a
///   bincode `TenzroOrderData`; foreign origins encode their own type).
/// - `escrow_id`: 32-byte hex id of the `EscrowManager` escrow already
///   locking the swapper's inputs. The caller is responsible for opening
///   the escrow before calling this RPC.
/// - `proof_route`: one of `layerzero`, `wormhole`, `debridge`,
///   `hyperlane` — the bridge route that will ferry the destination-side
///   fill proof back to origin.
///
/// On success returns `{ opened: true, order_id: "0x..." }`. Idempotent:
/// a second call with the same `(swapper, nonce, origin_chain_id,
/// fill_deadline, order_data_type, order_data)` returns the same
/// `order_id` and `{ opened: false }` if an envelope already exists.
async fn handle_open_7683_order(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    use tenzro_types::intent_7683::{
        compute_order_id, order_storage_key, CrossChainOrder, FillInstruction, Output,
        OrderState, ProofRoute, ResolvedCrossChainOrder, Tenzro7683Order, TenzroOrderData,
    };
    use tenzro_types::primitives::Timestamp;

    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;

    let settlement_contract = parse_hex_address_param(&params, "settlement_contract")?;
    let swapper = parse_hex_address_param(&params, "swapper")?;
    let nonce = params
        .get("nonce")
        .and_then(|v| v.as_u64())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing nonce (u64)".to_string(),
            data: None,
        })?;
    let origin_chain_id = params
        .get("origin_chain_id")
        .and_then(|v| v.as_u64())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing origin_chain_id (u32)".to_string(),
            data: None,
        })? as u32;
    let fill_deadline = params
        .get("fill_deadline")
        .and_then(|v| v.as_u64())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing fill_deadline (u32)".to_string(),
            data: None,
        })? as u32;
    let order_data_type = parse_hex_hash_param(&params, "order_data_type")?;
    let order_data_hex = params
        .get("order_data")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing order_data (hex)".to_string(),
            data: None,
        })?;
    let order_data = hex::decode(order_data_hex.trim_start_matches("0x")).map_err(|e| {
        JsonRpcError {
            code: -32602,
            message: format!("Invalid order_data hex: {}", e),
            data: None,
        }
    })?;
    let escrow_id = parse_hex_hash_param(&params, "escrow_id")?;
    let proof_route_str = params
        .get("proof_route")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing proof_route".to_string(),
            data: None,
        })?;
    let proof_route = match proof_route_str {
        "layerzero" => ProofRoute::LayerZero,
        "wormhole" => ProofRoute::Wormhole,
        "debridge" => ProofRoute::DeBridge,
        "hyperlane" => ProofRoute::Hyperlane,
        other => {
            return Err(JsonRpcError {
                code: -32602,
                message: format!(
                    "Unknown proof_route '{}' — expected one of layerzero, wormhole, debridge, hyperlane",
                    other
                ),
                data: None,
            });
        }
    };

    let order = CrossChainOrder {
        settlement_contract,
        swapper,
        nonce,
        origin_chain_id,
        fill_deadline,
        order_data_type,
        order_data: order_data.clone(),
    };
    let order_id = compute_order_id(&order);
    let storage_key = order_storage_key(&order_id);

    let storage = node.storage().ok_or_else(|| JsonRpcError {
        code: -32000,
        message: "Storage not available".to_string(),
        data: None,
    })?;

    // Idempotency — if an envelope at this id exists, return it without
    // mutation.
    if let Some(_existing) = storage
        .get(CF_SETTLEMENTS, &storage_key)
        .map_err(|e| JsonRpcError {
            code: -32000,
            message: format!("Storage error: {}", e),
            data: None,
        })?
    {
        return Ok(serde_json::json!({
            "opened": false,
            "order_id": format!("0x{}", hex::encode(order_id.as_bytes())),
        }));
    }

    // Resolve `min_received` / `max_spent` / `fill_instructions` from the
    // TenzroOrderData payload when the order is Tenzro-native. Foreign
    // origin payloads are stored verbatim and resolved by their own
    // settler.
    let (max_spent, min_received, fill_instructions) =
        if let Ok(td) = bincode::deserialize::<TenzroOrderData>(&order_data) {
            let max_spent: Vec<Output> = td
                .outputs
                .iter()
                .cloned()
                .map(|o| Output {
                    token: o.token,
                    amount: o.amount,
                    recipient: o.recipient,
                    chain_id: o.chain_id,
                })
                .collect();
            let min_received: Vec<Output> = td
                .inputs
                .iter()
                .map(|t| Output {
                    token: t.token.clone(),
                    amount: t.amount,
                    recipient: swapper.as_bytes().try_into().unwrap_or([0u8; 32]),
                    chain_id: origin_chain_id,
                })
                .collect();
            let fill_instructions = vec![FillInstruction {
                destination_chain_id: td.dest_chain_id,
                destination_settler: [0u8; 32],
                origin_data: order_data.clone(),
            }];
            (max_spent, min_received, fill_instructions)
        } else {
            (Vec::new(), Vec::new(), Vec::new())
        };

    let resolved = ResolvedCrossChainOrder {
        settlement_contract,
        swapper,
        nonce,
        origin_chain_id,
        fill_deadline,
        max_spent,
        min_received,
        fill_instructions,
    };

    let envelope = Tenzro7683Order {
        order_id,
        state: OrderState::Open,
        resolved,
        escrow_id,
        opened_at: Timestamp::now(),
        fill_deadline,
        filler: None,
        fill_proof_hash: None,
        proof_route,
    };

    let bytes = serde_json::to_vec(&envelope).map_err(|e| JsonRpcError {
        code: -32000,
        message: format!("Failed to serialize order envelope: {}", e),
        data: None,
    })?;
    storage
        .put(CF_SETTLEMENTS, &storage_key, &bytes)
        .map_err(|e| JsonRpcError {
            code: -32000,
            message: format!("Storage write error: {}", e),
            data: None,
        })?;

    Ok(serde_json::json!({
        "opened": true,
        "order_id": format!("0x{}", hex::encode(order_id.as_bytes())),
    }))
}

/// `tenzro_get7683Order` — fetch a single ERC-7683 cross-chain order envelope
/// by `order_id` (Agent-Swarm Spec 4 — wave 1, read path).
///
/// Params: `{ "order_id": "0x.." }` — 32-byte hex-encoded order id as
/// computed by `compute_order_id`.
///
/// Returns the persisted `Tenzro7683Order` envelope or a JSON-RPC error if
/// no order exists at that id. The envelope reports state, escrow handle,
/// fill deadline, filler (if assigned), fill-proof hash (if landed), and
/// proof route. Settler write paths land alongside the precompile + EIP-712
/// flow in a follow-up; this RPC is the canonical read for indexers and
/// solver UIs in the meantime.
async fn handle_get_7683_order(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    use tenzro_types::intent_7683::{Tenzro7683Order, ORDER_KEY_PREFIX};

    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;

    let order_id_hex = params
        .get("order_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing order_id".to_string(),
            data: None,
        })?;

    let stripped = order_id_hex.strip_prefix("0x").unwrap_or(order_id_hex);
    let order_id_bytes = hex::decode(stripped).map_err(|e| JsonRpcError {
        code: -32602,
        message: format!("Invalid order_id hex: {}", e),
        data: None,
    })?;
    if order_id_bytes.len() != 32 {
        return Err(JsonRpcError {
            code: -32602,
            message: "order_id must be 32 bytes".to_string(),
            data: None,
        });
    }

    let storage = node.storage().ok_or_else(|| JsonRpcError {
        code: -32000,
        message: "Storage not available".to_string(),
        data: None,
    })?;

    let mut key = Vec::with_capacity(ORDER_KEY_PREFIX.len() + 32);
    key.extend_from_slice(ORDER_KEY_PREFIX);
    key.extend_from_slice(&order_id_bytes);

    let bytes = storage
        .get(CF_SETTLEMENTS, &key)
        .map_err(|e| JsonRpcError {
            code: -32000,
            message: format!("Storage error: {}", e),
            data: None,
        })?
        .ok_or_else(|| JsonRpcError {
            code: -32000,
            message: format!("Order not found: 0x{}", hex::encode(&order_id_bytes)),
            data: None,
        })?;

    let order: Tenzro7683Order = serde_json::from_slice(&bytes).map_err(|e| JsonRpcError {
        code: -32000,
        message: format!("Failed to deserialize order: {}", e),
        data: None,
    })?;

    Ok(tenzro_7683_order_to_json(&order))
}

/// `tenzro_list7683Orders` — paginated scan of persisted ERC-7683 cross-chain
/// orders (Agent-Swarm Spec 4 — wave 1, read path).
///
/// Params (all optional):
/// - `state`: filter by order state — one of `open`, `awaiting_proof`,
///   `settled`, `refunded`, `force_refund_eligible`.
/// - `dest_chain`: u32 — filter by destination chain id (CAIP-2 numeric).
/// - `limit`: usize — cap on returned envelopes (default 50).
///
/// Returns `{ orders: [...], count: N }` where each entry is the same
/// JSON shape as `tenzro_get7683Order`. The scan walks the
/// `7683_origin:` prefix in `CF_SETTLEMENTS`; the dual `7683_dest:` keyspace
/// (fill idempotency guards, indexed on the destination side) is not
/// surfaced here.
async fn handle_list_7683_orders(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    use tenzro_types::intent_7683::{Tenzro7683Order, ORDER_KEY_PREFIX};

    let storage = node.storage().ok_or_else(|| JsonRpcError {
        code: -32000,
        message: "Storage not available".to_string(),
        data: None,
    })?;

    let limit = params
        .as_ref()
        .and_then(|p| p.get("limit"))
        .and_then(|v| v.as_u64())
        .unwrap_or(50) as usize;

    let state_filter = params
        .as_ref()
        .and_then(|p| p.get("state"))
        .and_then(|v| v.as_str())
        .map(|s| s.to_string());

    let dest_chain_filter = params
        .as_ref()
        .and_then(|p| p.get("dest_chain"))
        .and_then(|v| v.as_u64())
        .map(|n| n as u32);

    let keys = storage
        .get_keys_with_prefix(CF_SETTLEMENTS, ORDER_KEY_PREFIX)
        .map_err(|e| JsonRpcError {
            code: -32000,
            message: format!("Storage error: {}", e),
            data: None,
        })?;

    let mut orders = Vec::new();
    for key in keys.iter().take(limit * 4) {
        let Ok(Some(bytes)) = storage.get(CF_SETTLEMENTS, key) else {
            continue;
        };
        let Ok(order) = serde_json::from_slice::<Tenzro7683Order>(&bytes) else {
            continue;
        };

        if let Some(ref s) = state_filter {
            use tenzro_types::intent_7683::OrderState;
            let order_state_str = match order.state {
                OrderState::Open => "open",
                OrderState::AwaitingProof => "awaiting_proof",
                OrderState::Settled => "settled",
                OrderState::Refunded => "refunded",
                OrderState::ForceRefundEligible => "force_refund_eligible",
            };
            if order_state_str != s.as_str() {
                continue;
            }
        }

        if let Some(dc) = dest_chain_filter {
            // The destination chain lives inside the resolved order data; fall
            // through cleanly if any output matches the filter.
            let any_match = order
                .resolved
                .min_received
                .iter()
                .any(|o| o.chain_id == dc);
            if !any_match {
                continue;
            }
        }

        orders.push(tenzro_7683_order_to_json(&order));
        if orders.len() >= limit {
            break;
        }
    }

    Ok(serde_json::json!({
        "orders": orders,
        "count": orders.len(),
    }))
}

// ---- ERC-7683 destination-side fill RPCs (Agent-Swarm Spec 4) ---------------

/// Render a `FillRecord` as JSON for the read-side RPCs. Bytes are
/// hex-encoded with `0x` prefix to match the convention used by the
/// open-side `tenzro_7683_order_to_json` helper.
fn tenzro_7683_fill_to_json(record: &tenzro_types::intent_7683::FillRecord) -> Value {
    serde_json::json!({
        "order_id": format!("0x{}", hex::encode(record.order_id.as_bytes())),
        "origin_chain_id": record.origin_chain_id,
        "origin_settler": format!("0x{}", hex::encode(record.origin_settler.as_bytes())),
        "filler": format!("0x{}", hex::encode(record.filler.as_bytes())),
        "recipient": format!("0x{}", hex::encode(record.recipient)),
        "outputs": record.outputs.iter().map(|o| serde_json::json!({
            "token": format!("0x{}", hex::encode(&o.token)),
            "amount": format!("0x{}", hex::encode(o.amount)),
            "recipient": format!("0x{}", hex::encode(o.recipient)),
            "chain_id": o.chain_id,
        })).collect::<Vec<_>>(),
        "fill_tx_hash": format!("0x{}", hex::encode(record.fill_tx_hash.as_bytes())),
        "filled_at_ms": record.filled_at.as_millis(),
        "proof_route": record.proof_route.as_str(),
    })
}

/// Decode a 32-byte `Hash` from a `0x`-prefixed (or bare) hex string.
fn parse_hex_hash_param(
    params: &Value,
    field: &str,
) -> std::result::Result<tenzro_types::primitives::Hash, JsonRpcError> {
    let hex_str = params
        .get(field)
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: format!("Missing {}", field),
            data: None,
        })?;
    let stripped = hex_str.strip_prefix("0x").unwrap_or(hex_str);
    let bytes = hex::decode(stripped).map_err(|e| JsonRpcError {
        code: -32602,
        message: format!("Invalid {} hex: {}", field, e),
        data: None,
    })?;
    if bytes.len() != 32 {
        return Err(JsonRpcError {
            code: -32602,
            message: format!("{} must be 32 bytes", field),
            data: None,
        });
    }
    let mut arr = [0u8; 32];
    arr.copy_from_slice(&bytes);
    Ok(tenzro_types::primitives::Hash::new(arr))
}

/// Decode a 32-byte `Address` from a `0x`-prefixed (or bare) hex string.
fn parse_hex_address_param(
    params: &Value,
    field: &str,
) -> std::result::Result<tenzro_types::primitives::Address, JsonRpcError> {
    let hex_str = params
        .get(field)
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: format!("Missing {}", field),
            data: None,
        })?;
    let stripped = hex_str.strip_prefix("0x").unwrap_or(hex_str);
    let bytes = hex::decode(stripped).map_err(|e| JsonRpcError {
        code: -32602,
        message: format!("Invalid {} hex: {}", field, e),
        data: None,
    })?;
    if bytes.len() != 32 {
        return Err(JsonRpcError {
            code: -32602,
            message: format!("{} must be 32 bytes", field),
            data: None,
        });
    }
    let mut arr = [0u8; 32];
    arr.copy_from_slice(&bytes);
    Ok(tenzro_types::primitives::Address::new(arr))
}

/// Decode a 32-byte raw byte slot from a `0x`-prefixed (or bare) hex string.
fn parse_hex_bytes32_param(
    params: &Value,
    field: &str,
) -> std::result::Result<[u8; 32], JsonRpcError> {
    let hex_str = params
        .get(field)
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: format!("Missing {}", field),
            data: None,
        })?;
    let stripped = hex_str.strip_prefix("0x").unwrap_or(hex_str);
    let bytes = hex::decode(stripped).map_err(|e| JsonRpcError {
        code: -32602,
        message: format!("Invalid {} hex: {}", field, e),
        data: None,
    })?;
    if bytes.len() != 32 {
        return Err(JsonRpcError {
            code: -32602,
            message: format!("{} must be 32 bytes", field),
            data: None,
        });
    }
    let mut arr = [0u8; 32];
    arr.copy_from_slice(&bytes);
    Ok(arr)
}

/// `tenzro_recordFill7683` — write path for the destination-side fill
/// registry. Idempotent: a second call for an `order_id` already filled on
/// this Tenzro replica returns JSON-RPC error `-32010` (`OrderAlreadyFilled`)
/// without mutation.
///
/// This RPC mirrors what the destination settler precompile will call once
/// it lands. Today it lets indexers, integration tests, and the bridge
/// adapters that ferry proof back to origin prove against a known-recorded
/// fill. Fund movement (pulling outputs from the solver, crediting the
/// recipient) is **not** done here — that's the precompile's job. This
/// registry is the idempotency guard, not the value transfer.
///
/// Params (all required, all hex-encoded with optional `0x` prefix):
/// - `order_id`: 32-byte hex, the canonical 7683 order id.
/// - `origin_chain_id`: u32, the chain where the order was opened.
/// - `origin_settler`: 32-byte hex address of the origin-chain settler
///   contract (chain-discriminated bytes32).
/// - `filler`: 32-byte hex Tenzro address of the solver who filled.
/// - `recipient`: 32-byte hex chain-discriminated recipient bytes.
/// - `outputs`: array of `{ token: hex, amount: 32-byte hex, recipient:
///   32-byte hex, chain_id: u32 }` — exact `Output` set the solver
///   delivered.
/// - `fill_tx_hash`: 32-byte hex of the Tenzro transaction in which the
///   fill transfers happened.
/// - `filled_at_ms`: u64, wall-clock timestamp in milliseconds.
/// - `proof_route`: one of `layerzero`, `wormhole`, `debridge`,
///   `hyperlane` — the route designated by the order's `proof_route`.
///
/// On success returns `{ recorded: true, order_id: "0x..." }`.
async fn handle_record_fill_7683(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    use tenzro_types::intent_7683::{FillRecord, Output, ProofRoute};
    use tenzro_types::primitives::Timestamp;

    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;

    let order_id = parse_hex_hash_param(&params, "order_id")?;
    let origin_chain_id = params
        .get("origin_chain_id")
        .and_then(|v| v.as_u64())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing origin_chain_id (u32)".to_string(),
            data: None,
        })? as u32;
    let origin_settler = parse_hex_address_param(&params, "origin_settler")?;
    let filler = parse_hex_address_param(&params, "filler")?;
    let recipient = parse_hex_bytes32_param(&params, "recipient")?;
    let fill_tx_hash = parse_hex_hash_param(&params, "fill_tx_hash")?;
    let filled_at_ms = params
        .get("filled_at_ms")
        .and_then(|v| v.as_i64())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing filled_at_ms (i64)".to_string(),
            data: None,
        })?;
    let proof_route_str = params
        .get("proof_route")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing proof_route".to_string(),
            data: None,
        })?;
    let proof_route = match proof_route_str {
        "layerzero" => ProofRoute::LayerZero,
        "wormhole" => ProofRoute::Wormhole,
        "debridge" => ProofRoute::DeBridge,
        "hyperlane" => ProofRoute::Hyperlane,
        other => {
            return Err(JsonRpcError {
                code: -32602,
                message: format!(
                    "Unknown proof_route '{}' — expected one of layerzero, wormhole, debridge, hyperlane",
                    other
                ),
                data: None,
            });
        }
    };

    let outputs_array = params
        .get("outputs")
        .and_then(|v| v.as_array())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing outputs array".to_string(),
            data: None,
        })?;

    let mut outputs = Vec::with_capacity(outputs_array.len());
    for (idx, raw_output) in outputs_array.iter().enumerate() {
        let token_hex = raw_output
            .get("token")
            .and_then(|v| v.as_str())
            .ok_or_else(|| JsonRpcError {
                code: -32602,
                message: format!("outputs[{}].token missing", idx),
                data: None,
            })?;
        let token =
            hex::decode(token_hex.strip_prefix("0x").unwrap_or(token_hex)).map_err(|e| {
                JsonRpcError {
                    code: -32602,
                    message: format!("outputs[{}].token invalid hex: {}", idx, e),
                    data: None,
                }
            })?;
        let amount = parse_hex_bytes32_param(raw_output, "amount").map_err(|mut e| {
            e.message = format!("outputs[{}]: {}", idx, e.message);
            e
        })?;
        let out_recipient = parse_hex_bytes32_param(raw_output, "recipient").map_err(|mut e| {
            e.message = format!("outputs[{}]: {}", idx, e.message);
            e
        })?;
        let chain_id = raw_output
            .get("chain_id")
            .and_then(|v| v.as_u64())
            .ok_or_else(|| JsonRpcError {
                code: -32602,
                message: format!("outputs[{}].chain_id missing (u32)", idx),
                data: None,
            })? as u32;
        outputs.push(Output {
            token,
            amount,
            recipient: out_recipient,
            chain_id,
        });
    }

    let record = FillRecord {
        order_id,
        origin_chain_id,
        origin_settler,
        filler,
        recipient,
        outputs,
        fill_tx_hash,
        filled_at: Timestamp::new(filled_at_ms),
        proof_route,
    };

    let registry = node.spec4_fill_registry().ok_or_else(|| JsonRpcError {
        code: -32000,
        message: "Spec4FillRegistry not available".to_string(),
        data: None,
    })?;

    registry.record_fill(record).map_err(|e| {
        // OrderAlreadyFilled gets its own JSON-RPC error code so callers can
        // distinguish "duplicate fill rejected" from "storage broke".
        let code = match &e {
            tenzro_settlement::SettlementError::OrderAlreadyFilled(_) => -32010,
            _ => -32000,
        };
        JsonRpcError {
            code,
            message: e.to_string(),
            data: None,
        }
    })?;

    Ok(serde_json::json!({
        "recorded": true,
        "order_id": format!("0x{}", hex::encode(order_id.as_bytes())),
    }))
}

/// `tenzro_getFill7683` — fetch the destination-side fill record for an
/// `order_id`. Returns the record JSON if recorded, JSON-RPC error -32000
/// (`Fill not found`) otherwise.
async fn handle_get_fill_7683(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let order_id = parse_hex_hash_param(&params, "order_id")?;

    let registry = node.spec4_fill_registry().ok_or_else(|| JsonRpcError {
        code: -32000,
        message: "Spec4FillRegistry not available".to_string(),
        data: None,
    })?;

    let record = registry.get_fill(&order_id).ok_or_else(|| JsonRpcError {
        code: -32000,
        message: format!("Fill not found for order_id 0x{}", hex::encode(order_id.as_bytes())),
        data: None,
    })?;

    Ok(tenzro_7683_fill_to_json(&record))
}

/// `tenzro_listFills7683` — enumerate every recorded destination-side
/// fill on this node. Returns `{ fills: [...], count: N }` with no
/// pagination (the registry is small per validator — the destination
/// settler enforces single-shot per `order_id` so cardinality grows at
/// most once per cross-chain order ever filled here).
async fn handle_list_fills_7683(
    node: &Arc<TenzroNode>,
) -> std::result::Result<Value, JsonRpcError> {
    let registry = node.spec4_fill_registry().ok_or_else(|| JsonRpcError {
        code: -32000,
        message: "Spec4FillRegistry not available".to_string(),
        data: None,
    })?;

    let fills: Vec<Value> = registry
        .list_fills()
        .iter()
        .map(tenzro_7683_fill_to_json)
        .collect();
    let count = fills.len();

    Ok(serde_json::json!({
        "fills": fills,
        "count": count,
    }))
}

// ========================================================================
// Spec 8: Adaptive burn governance dial — read RPCs.
//
// The auto-proposal generator, the EIP-1559 fee-market consumer, and the
// real epoch observer (aggregating from UsageTracker + the burn ledger)
// land alongside the governance executor wiring in a later wave. The four
// handlers below expose the protocol-side primitives — current dial,
// latest snapshot, recommendation, and a placeholder proposal list — so
// indexers and explorers can render adaptive-burn state today.
// ========================================================================

fn supply_metrics_to_json(snapshot: &tenzro_token::adaptive_burn::SupplyMetricsSnapshot) -> Value {
    serde_json::json!({
        "block_height": snapshot.block_height.as_u64(),
        "captured_at_ms": snapshot.captured_at.as_millis(),
        "circulating_supply": snapshot.circulating_supply.to_string(),
        "epoch_supply_delta": snapshot.epoch_supply_delta.to_string(),
        "rolling_window_supply_delta_bps": snapshot.rolling_window_supply_delta_bps,
        "burn_breakdown": {
            "base_fee": snapshot.burn_breakdown.base_fee.to_string(),
            "local_fee": snapshot.burn_breakdown.local_fee.to_string(),
            "paymaster": snapshot.burn_breakdown.paymaster.to_string(),
            "slash": snapshot.burn_breakdown.slash.to_string(),
            "total": snapshot.burn_breakdown.total().to_string(),
        },
        "emission_breakdown": {
            "staking_rewards": snapshot.emission_breakdown.staking_rewards.to_string(),
            "treasury_emissions": snapshot.emission_breakdown.treasury_emissions.to_string(),
            "total": snapshot.emission_breakdown.total().to_string(),
        },
    })
}

