// ============================================================================
// Audio ASR — Moonshine, Whisper, Parakeet, Canary, Distil-Whisper
// ============================================================================

/// `tenzro_loadAudioModel`: load an ONNX ASR encoder + decoder bundle from
/// local paths and register it under `model_id`.
///
/// Params (explicit family):
/// `{ model_id, family: "moonshine" | "whisper", encoder_path, decoder_path,
///    tokenizer_path, max_audio_seconds?, whisper_variant? }`
///
/// Params (catalog-driven):
/// `{ model_id, catalog_id, encoder_path, decoder_path, tokenizer_path }`
/// — `family` and `max_audio_seconds` come from the catalog entry; for
/// Whisper-family entries `whisper_variant` is inferred from the catalog
/// id (`distil-whisper-*-en` → DistilEn, `distil-whisper-large-v3` →
/// DistilLargeV3, `whisper-large-v3-turbo` → LargeV3Turbo).
///
/// `whisper_variant` (when explicit): `"distil-en" | "distil-large-v3" |
/// "large-v3-turbo"`.
async fn handle_load_audio_model(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let p = params.ok_or_else(|| missing_param("params"))?;
    let model_id = p
        .get("model_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| missing_param("model_id"))?
        .to_string();
    let encoder_path = p
        .get("encoder_path")
        .and_then(|v| v.as_str())
        .ok_or_else(|| missing_param("encoder_path"))?
        .to_string();
    let decoder_path = p
        .get("decoder_path")
        .and_then(|v| v.as_str())
        .ok_or_else(|| missing_param("decoder_path"))?
        .to_string();
    // `tokenizer_path` is required for moonshine/whisper (tokenizer.json).
    // Parakeet uses `vocab_path` instead — we resolve per-family below.
    let tokenizer_path_opt = p
        .get("tokenizer_path")
        .and_then(|v| v.as_str())
        .map(|s| s.to_string());
    let preprocessor_path_opt = p
        .get("preprocessor_path")
        .and_then(|v| v.as_str())
        .map(|s| s.to_string());
    let vocab_path_opt = p
        .get("vocab_path")
        .and_then(|v| v.as_str())
        .map(|s| s.to_string());

    // Resolve family + max_audio_seconds + whisper variant. Either from
    // the catalog (catalog_id) or from explicit params.
    let (family, max_audio_seconds, whisper_variant_from_catalog) =
        if let Some(catalog_id) = p.get("catalog_id").and_then(|v| v.as_str()) {
            let entry = get_audio_model_by_id(catalog_id).ok_or_else(|| JsonRpcError {
                code: -32602,
                message: format!("Unknown audio catalog_id '{}'", catalog_id),
                data: None,
            })?;
            let inferred_variant = match entry.id.as_str() {
                "distil-whisper-small-en" | "distil-whisper-medium-en" => Some("distil-en"),
                "distil-whisper-large-v3" => Some("distil-large-v3"),
                "whisper-large-v3-turbo" => Some("large-v3-turbo"),
                _ => None,
            }
            .map(|s| s.to_string());
            (entry.family.clone(), entry.max_audio_seconds, inferred_variant)
        } else {
            let family = p
                .get("family")
                .and_then(|v| v.as_str())
                .ok_or_else(|| missing_param("family"))?
                .to_string();
            let max_audio_seconds = p
                .get("max_audio_seconds")
                .and_then(|v| v.as_u64())
                .unwrap_or(30) as u32;
            (family, max_audio_seconds, None)
        };

    match family.as_str() {
        "moonshine" => {
            let tokenizer_path = tokenizer_path_opt
                .as_deref()
                .ok_or_else(|| missing_param("tokenizer_path"))?;
            node.audio_runtime
                .load_moonshine(
                    model_id.clone(),
                    &encoder_path,
                    &decoder_path,
                    tokenizer_path,
                    max_audio_seconds,
                )
                .map_err(forecast_err)?;
        }
        "whisper" => {
            let tokenizer_path = tokenizer_path_opt
                .as_deref()
                .ok_or_else(|| missing_param("tokenizer_path"))?;
            let variant_str = p
                .get("whisper_variant")
                .and_then(|v| v.as_str())
                .map(|s| s.to_string())
                .or(whisper_variant_from_catalog)
                .ok_or_else(|| JsonRpcError {
                    code: -32602,
                    message: "missing 'whisper_variant' (one of: distil-en, distil-large-v3, large-v3-turbo)".to_string(),
                    data: None,
                })?;
            let variant = match variant_str.as_str() {
                "distil-en" => WhisperFamily::DistilEn,
                "distil-large-v3" => WhisperFamily::DistilLargeV3,
                "large-v3-turbo" => WhisperFamily::LargeV3Turbo,
                other => {
                    return Err(JsonRpcError {
                        code: -32602,
                        message: format!(
                            "unknown whisper_variant '{}' (expected: distil-en, distil-large-v3, large-v3-turbo)",
                            other
                        ),
                        data: None,
                    });
                }
            };
            node.audio_runtime
                .load_whisper(
                    model_id.clone(),
                    &encoder_path,
                    &decoder_path,
                    tokenizer_path,
                    variant,
                    max_audio_seconds,
                )
                .map_err(forecast_err)?;
        }
        "parakeet" => {
            let preprocessor_path = preprocessor_path_opt
                .as_deref()
                .ok_or_else(|| missing_param("preprocessor_path"))?;
            let vocab_path = vocab_path_opt
                .as_deref()
                .ok_or_else(|| missing_param("vocab_path"))?;
            node.audio_runtime
                .load_parakeet(
                    model_id.clone(),
                    preprocessor_path,
                    &encoder_path,
                    &decoder_path,
                    vocab_path,
                    max_audio_seconds,
                )
                .map_err(forecast_err)?;
        }
        "canary" => {
            let preprocessor_path = preprocessor_path_opt
                .as_deref()
                .ok_or_else(|| missing_param("preprocessor_path"))?;
            let vocab_path = vocab_path_opt
                .as_deref()
                .ok_or_else(|| missing_param("vocab_path"))?;
            // Canary needs source_lang + target_lang to build the
            // 10-token decoder prefix. Both default to "en" (English
            // ASR with no translation) when omitted.
            let source_lang = p
                .get("source_lang")
                .and_then(|v| v.as_str())
                .unwrap_or("en")
                .to_string();
            let target_lang = p
                .get("target_lang")
                .and_then(|v| v.as_str())
                .unwrap_or("en")
                .to_string();
            node.audio_runtime
                .load_canary(
                    model_id.clone(),
                    preprocessor_path,
                    &encoder_path,
                    &decoder_path,
                    vocab_path,
                    source_lang,
                    target_lang,
                    max_audio_seconds,
                )
                .map_err(forecast_err)?;
        }
        other => {
            return Err(JsonRpcError {
                code: -32602,
                message: format!(
                    "unknown audio family '{}' (expected: moonshine, whisper, parakeet, canary)",
                    other
                ),
                data: None,
            });
        }
    }

    Ok(serde_json::json!({
        "model_id": model_id,
        "loaded": true,
        "family": family,
        "max_audio_seconds": max_audio_seconds,
    }))
}

async fn handle_unload_audio_model(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let p = params.ok_or_else(|| missing_param("params"))?;
    let model_id = p
        .get("model_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| missing_param("model_id"))?;
    let removed = node.audio_runtime.unregister(model_id);
    Ok(serde_json::json!({ "model_id": model_id, "removed": removed }))
}

