// ── Canton/DAML handlers ───────────────────────────────────────────

async fn handle_list_canton_domains(
    node: &Arc<TenzroNode>,
) -> std::result::Result<Value, JsonRpcError> {
    let config = node.config();
    if !config.canton.enabled {
        return Ok(serde_json::json!({
            "enabled": false,
            "domains": [],
            "message": "Canton/DAML is not enabled on this node",
        }));
    }

    // Reach the live CantonAdapter via the bridge subsystem. If Canton is
    // configured-enabled but the adapter failed to attach (e.g. participant
    // unreachable at startup), surface that as -32000 rather than masking
    // with stale "configured" data.
    let adapter = canton_adapter_or_err(node)?;
    let domains: Vec<Value> = adapter
        .list_synchronizers()
        .into_iter()
        .map(|c| {
            serde_json::json!({
                "id": c.chain_id,
                "name": c.name,
                "native_token": c.native_token,
                "finality_time_secs": c.finality_time_secs,
            })
        })
        .collect();

    Ok(serde_json::json!({
        "enabled": true,
        "domains": domains,
    }))
}

async fn handle_list_daml_contracts(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let config = node.config();
    if !config.canton.enabled {
        return Err(JsonRpcError {
            code: -32603,
            message: "Canton/DAML is not enabled on this node".to_string(),
            data: None,
        });
    }

    // The v2 active-contracts endpoint requires at least one template id.
    // Accept either `template_ids: [..]` for explicit selection or a single
    // `template_id: ".."` shorthand. The optional `query` object is the
    // structural filter applied client-side against `createArguments`.
    let (template_ids, query) = match &params {
        Some(p) => {
            let template_ids = if let Some(arr) = p.get("template_ids").and_then(|v| v.as_array()) {
                arr.iter()
                    .filter_map(|v| v.as_str().map(|s| s.to_string()))
                    .collect::<Vec<_>>()
            } else if let Some(t) = p.get("template_id").and_then(|v| v.as_str()) {
                vec![t.to_string()]
            } else {
                Vec::new()
            };
            let query = p.get("query").cloned().unwrap_or(Value::Null);
            (template_ids, query)
        }
        None => (Vec::new(), Value::Null),
    };

    if template_ids.is_empty() {
        return Err(JsonRpcError {
            code: -32602,
            message: "Missing template_ids (Canton v2 active-contracts requires at least one)"
                .to_string(),
            data: None,
        });
    }

    let adapter = canton_adapter_or_err(node)?;
    let contracts = adapter
        .query_active_contracts(template_ids.clone(), query.clone())
        .await
        .map_err(|e| {
            tracing::error!("Canton query_active_contracts failed: {}", e);
            JsonRpcError {
                code: -32000,
                message: "Canton query failed (see node logs)".to_string(),
                data: None,
            }
        })?;

    let projected: Vec<Value> = contracts
        .into_iter()
        .map(|c| {
            serde_json::json!({
                "contract_id": c.contract_id,
                "template_id": c.template_id,
                "payload": c.payload,
            })
        })
        .collect();

    Ok(serde_json::json!({
        "contracts": projected,
        "template_ids": template_ids,
        "query": query,
    }))
}

async fn handle_submit_daml_command(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let config = node.config();
    if !config.canton.enabled {
        return Err(JsonRpcError {
            code: -32603,
            message: "Canton/DAML is not enabled on this node".to_string(),
            data: None,
        });
    }

    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;

    let command_type = params
        .get("command_type")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing command_type (create | exercise)".to_string(),
            data: None,
        })?;

    let template_id = params
        .get("template_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing template_id".to_string(),
            data: None,
        })?
        .to_string();

    let adapter = canton_adapter_or_err(node)?;

    // Optional per-submission `actAs` override. Set by per-agent spawning so
    // contracts created by the agent name the agent's allocated party (not
    // the operator's participant-default party).
    let act_as_party = params.get("act_as").and_then(|v| v.as_str());

    let result = match command_type {
        "create" => {
            let create_arguments = params
                .get("create_arguments")
                .cloned()
                .unwrap_or(Value::Null);
            adapter
                .submit_create_command_as(&template_id, create_arguments, act_as_party)
                .await
        }
        "exercise" => {
            let contract_id = params
                .get("contract_id")
                .and_then(|v| v.as_str())
                .ok_or_else(|| JsonRpcError {
                    code: -32602,
                    message: "Missing contract_id (required for exercise)".to_string(),
                    data: None,
                })?;
            let choice = params
                .get("choice")
                .and_then(|v| v.as_str())
                .ok_or_else(|| JsonRpcError {
                    code: -32602,
                    message: "Missing choice (required for exercise)".to_string(),
                    data: None,
                })?;
            let argument = params
                .get("choice_argument")
                .cloned()
                .unwrap_or(Value::Null);
            adapter
                .submit_exercise_command_as(
                    contract_id,
                    &template_id,
                    choice,
                    argument,
                    act_as_party,
                )
                .await
        }
        other => {
            return Err(JsonRpcError {
                code: -32602,
                message: format!(
                    "Unsupported command_type '{}' (supported: create, exercise)",
                    other
                ),
                data: None,
            });
        }
    };

    result.map_err(|e| {
        tracing::error!("Canton submit_daml_command failed: {}", e);
        JsonRpcError {
            code: -32000,
            message: "Canton command submission failed (see node logs)".to_string(),
            data: None,
        }
    })
}

/// Allocates a fresh Daml party on the configured Canton participant.
///
/// Used by `tenzro-agent-kit` at spawn time for DAML-backed agent
/// templates: each agent receives its own on-ledger party so contracts it
/// creates name the agent (not the operator's default `act_as_party`) as
/// `actAs`. The allocated party id is then stored on `SpawnedAgent` and
/// passed through to the executor's DAML dispatch path on every
/// `submit-and-wait-for-transaction` call.
///
/// Params:
///   - `party_id_hint`: human-readable label suggested to the participant
///     (e.g. `"agent-<uuid>"`); the participant may suffix-encode it.
///   - `display_name` (optional): metadata stored alongside the party.
///
/// Returns: `{ "party_id": "<canonical-id>" }`.
async fn handle_allocate_party(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let config = node.config();
    if !config.canton.enabled {
        return Err(JsonRpcError {
            code: -32603,
            message: "Canton/DAML is not enabled on this node".to_string(),
            data: None,
        });
    }

    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;

    let party_id_hint = params
        .get("party_id_hint")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing party_id_hint".to_string(),
            data: None,
        })?;

    let display_name = params.get("display_name").and_then(|v| v.as_str());

    let adapter = canton_adapter_or_err(node)?;
    let party_id = adapter
        .allocate_party(party_id_hint, display_name)
        .await
        .map_err(|e| {
            tracing::error!("Canton allocate_party failed: {}", e);
            JsonRpcError {
                code: -32000,
                message: "Canton party allocation failed (see node logs)".to_string(),
                data: None,
            }
        })?;

    Ok(serde_json::json!({
        "party_id": party_id,
        "party_id_hint": party_id_hint,
    }))
}

// ── Canton 3.5+ JSON Ledger API extension handlers (M11 wave) ────────
//
// These ten handlers expose the bridge adapter's new Canton 3.5+ methods
// as JSON-RPC endpoints. Each is canton-scoped (requires
// `X-Tenzro-Api-Key` with `canton` scope; gating happens upstream in the
// dispatch layer) and short-circuits early when Canton is disabled.

async fn handle_canton_upload_dar(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let config = node.config();
    if !config.canton.enabled {
        return Err(JsonRpcError {
            code: -32603,
            message: "Canton/DAML is not enabled on this node".to_string(),
            data: None,
        });
    }
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let dar_b64 = params
        .get("dar_content_base64")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing dar_content_base64 (base64-encoded DAR bytes)".to_string(),
            data: None,
        })?;
    use base64::{engine::general_purpose::STANDARD as B64, Engine as _};
    let dar_bytes = B64.decode(dar_b64).map_err(|e| JsonRpcError {
        code: -32602,
        message: format!("Invalid base64 DAR content: {}", e),
        data: None,
    })?;
    let adapter = canton_adapter_or_err(node)?;
    let result = adapter.upload_dar(dar_bytes).await.map_err(|e| {
        tracing::error!("Canton upload_dar failed: {}", e);
        JsonRpcError {
            code: -32000,
            message: format!("Canton upload_dar failed: {}", e),
            data: None,
        }
    })?;
    Ok(result)
}

