// ── API key management handlers ─────────────────────────────────────
//
// API keys gate access to scoped RPC surfaces (currently `tenzro_*Canton*`).
// Issuance returns the plaintext key exactly once; afterwards only the
// SHA-256 hash and the non-secret `key_id` handle are persisted in
// `CF_API_KEYS`. Revocation is by `key_id`.
//
// Issuance and revocation themselves are gated by the operator admin
// token (`X-Tenzro-Admin-Token` header), enforced upstream in
// `gate_admin_token` at the dispatch layer. Handlers therefore do not
// re-check authentication — when invoked, the request has already
// cleared the gate. Fail-closed: a node started without
// `TENZRO_ADMIN_TOKEN` rejects every gated call regardless of input.

async fn handle_create_api_key(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    use crate::api_key::{ApiKeyScope, KeyClass};

    let mgr = node.api_key_manager().ok_or_else(|| JsonRpcError {
        code: -32603,
        message: "API key manager is not initialized".to_string(),
        data: None,
    })?;

    let params = params.unwrap_or_else(|| serde_json::json!({}));

    let label = params
        .get("label")
        .and_then(|v| v.as_str())
        .unwrap_or("unnamed")
        .to_string();

    let subject = params
        .get("subject")
        .and_then(|v| v.as_str())
        .map(|s| s.to_string());

    let scopes_raw = params
        .get("scopes")
        .and_then(|v| v.as_array())
        .cloned()
        .unwrap_or_else(|| vec![Value::String("canton".to_string())]);

    let mut scopes = Vec::new();
    for v in scopes_raw {
        let s = v.as_str().ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "scopes entries must be strings".to_string(),
            data: None,
        })?;
        let scope = match s {
            "canton" => ApiKeyScope::Canton,
            other => {
                return Err(JsonRpcError {
                    code: -32602,
                    message: format!("Unknown scope: {}", other),
                    data: None,
                });
            }
        };
        scopes.push(scope);
    }

    // `class` defaults to `subject` for the common developer-key path.
    // `operator_protected` is the operator's self-lockdown class —
    // accept it but require an explicit confirmation flag so a slipped
    // typo doesn't mint a key the operator cannot revoke via RPC.
    let class_str = params
        .get("class")
        .and_then(|v| v.as_str())
        .unwrap_or("subject");
    let class = KeyClass::from_str(class_str).ok_or_else(|| JsonRpcError {
        code: -32602,
        message: format!(
            "Unknown class: {} (expected operator_protected | subject | operator_internal)",
            class_str
        ),
        data: None,
    })?;
    if matches!(class, KeyClass::OperatorProtected) {
        let confirmed = params
            .get("confirm_operator_protected")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        if !confirmed {
            return Err(JsonRpcError {
                code: -32602,
                message: "class=operator_protected requires confirm_operator_protected:true (this key cannot be revoked via RPC, including by an admin token)".to_string(),
                data: None,
            });
        }
    }

    let issued = mgr
        .issue(subject, label, scopes, class)
        .map_err(|e| JsonRpcError {
            code: -32603,
            message: format!("issue API key: {}", e),
            data: None,
        })?;

    Ok(serde_json::json!({
        "key": issued.key,
        "key_id": issued.record.key_id,
        "label": issued.record.label,
        "subject": issued.record.subject,
        "scopes": issued.record.scopes.iter().map(|s| s.as_str()).collect::<Vec<_>>(),
        "class": issued.record.class.as_str(),
        "created_at": issued.record.created_at,
        "note": "Save the `key` field now — it is shown only once.",
    }))
}

async fn handle_revoke_api_key(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    use crate::api_key::AdminRevokeOutcome;

    let mgr = node.api_key_manager().ok_or_else(|| JsonRpcError {
        code: -32603,
        message: "API key manager is not initialized".to_string(),
        data: None,
    })?;

    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;

    let key_id = params
        .get("key_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing key_id".to_string(),
            data: None,
        })?;

    let outcome = mgr.revoke_by_id_admin(key_id).map_err(|e| JsonRpcError {
        code: -32603,
        message: format!("revoke API key: {}", e),
        data: None,
    })?;

    match outcome {
        AdminRevokeOutcome::Revoked => Ok(serde_json::json!({
            "key_id": key_id,
            "revoked": true,
        })),
        AdminRevokeOutcome::NotFound => Ok(serde_json::json!({
            "key_id": key_id,
            "revoked": false,
        })),
        AdminRevokeOutcome::Protected => Err(JsonRpcError {
            code: -32004,
            message: "operator-protected key cannot be revoked via RPC (rotate the operator secret + restart the node)".to_string(),
            data: Some(serde_json::json!({ "key_id": key_id, "class": "operator_protected" })),
        }),
    }
}

async fn handle_list_api_keys(
    node: &Arc<TenzroNode>,
) -> std::result::Result<Value, JsonRpcError> {
    let mgr = node.api_key_manager().ok_or_else(|| JsonRpcError {
        code: -32603,
        message: "API key manager is not initialized".to_string(),
        data: None,
    })?;

    let records: Vec<Value> = mgr
        .list()
        .into_iter()
        .map(|r| {
            serde_json::json!({
                "key_id": r.key_id,
                "subject": r.subject,
                "label": r.label,
                "scopes": r.scopes.iter().map(|s| s.as_str()).collect::<Vec<_>>(),
                "class": r.class.as_str(),
                "created_at": r.created_at,
                "revoked_at": r.revoked_at,
                "active": r.is_active(),
            })
        })
        .collect();

    Ok(serde_json::json!({ "keys": records }))
}

// ── Subject-gated API key handlers ──────────────────────────────────
//
// These RPCs let a key holder list and revoke their own keys without
// the operator admin token. They are gated only by `X-Tenzro-Api-Key`
// (no admin token required); the caller's `subject` is recovered from
// the presented key, and only records whose `subject` matches that
// value are visible / revokable.
//
// The presented key must be active. The `class` field on each record
// still drives revoke admissibility — only `KeyClass::Subject` records
// are revokable via `tenzro_revokeMyApiKey`.
//
// The header itself is forwarded into the handler via the `api_key`
// param threaded by `handle_request` — the gate at `gate_api_key`
// does NOT cover these methods (since they themselves serve key
// management, not Canton), so the handler MUST do its own auth.

async fn handle_revoke_my_api_key(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
    api_key: Option<&str>,
) -> std::result::Result<Value, JsonRpcError> {
    use crate::api_key::SubjectRevokeOutcome;

    let mgr = node.api_key_manager().ok_or_else(|| JsonRpcError {
        code: -32603,
        message: "API key manager is not initialized".to_string(),
        data: None,
    })?;

    let presented = api_key.ok_or_else(|| JsonRpcError {
        code: -32004,
        message: "Unauthorized: missing X-Tenzro-Api-Key header".to_string(),
        data: None,
    })?;

    let caller = mgr.lookup(presented).ok_or_else(|| JsonRpcError {
        code: -32004,
        message: "Unauthorized: API key is unknown or revoked".to_string(),
        data: None,
    })?;

    let caller_subject = caller.subject.clone().ok_or_else(|| JsonRpcError {
        code: -32004,
        message: "Unauthorized: presented key has no subject — subject-gated revoke is not applicable".to_string(),
        data: None,
    })?;

    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let target = params
        .get("key_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing key_id".to_string(),
            data: None,
        })?;

    let outcome = mgr
        .revoke_by_subject(&caller_subject, target)
        .map_err(|e| JsonRpcError {
            code: -32603,
            message: format!("subject-revoke API key: {}", e),
            data: None,
        })?;

    match outcome {
        SubjectRevokeOutcome::Revoked => Ok(serde_json::json!({
            "key_id": target,
            "revoked": true,
        })),
        // NotFound and NotYours map to the same error — a caller cannot
        // distinguish "this key doesn't exist on this node" from "it
        // exists but belongs to a different subject", since the latter
        // would leak ownership metadata.
        SubjectRevokeOutcome::NotFound | SubjectRevokeOutcome::NotYours => Err(JsonRpcError {
            code: -32004,
            message: "Unauthorized: no active key with that key_id belongs to your subject".to_string(),
            data: None,
        }),
        SubjectRevokeOutcome::NotSubjectRevokable => Err(JsonRpcError {
            code: -32004,
            message: "key is not subject-revokable (operator-internal or operator-protected class)".to_string(),
            data: Some(serde_json::json!({ "key_id": target })),
        }),
    }
}

async fn handle_list_my_api_keys(
    node: &Arc<TenzroNode>,
    api_key: Option<&str>,
) -> std::result::Result<Value, JsonRpcError> {
    let mgr = node.api_key_manager().ok_or_else(|| JsonRpcError {
        code: -32603,
        message: "API key manager is not initialized".to_string(),
        data: None,
    })?;

    let presented = api_key.ok_or_else(|| JsonRpcError {
        code: -32004,
        message: "Unauthorized: missing X-Tenzro-Api-Key header".to_string(),
        data: None,
    })?;
    let caller = mgr.lookup(presented).ok_or_else(|| JsonRpcError {
        code: -32004,
        message: "Unauthorized: API key is unknown or revoked".to_string(),
        data: None,
    })?;
    let caller_subject = caller.subject.clone().ok_or_else(|| JsonRpcError {
        code: -32004,
        message: "Unauthorized: presented key has no subject".to_string(),
        data: None,
    })?;

    let records: Vec<Value> = mgr
        .list_by_subject(&caller_subject)
        .into_iter()
        .map(|r| {
            serde_json::json!({
                "key_id": r.key_id,
                "subject": r.subject,
                "label": r.label,
                "scopes": r.scopes.iter().map(|s| s.as_str()).collect::<Vec<_>>(),
                "class": r.class.as_str(),
                "created_at": r.created_at,
                "revoked_at": r.revoked_at,
                "active": r.is_active(),
            })
        })
        .collect();

    Ok(serde_json::json!({ "keys": records, "subject": caller_subject }))
}

// ── Staking & Provider handlers ────────────────────────────────────

async fn handle_stake(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;

    // Extract from array wrapper if present (CLI sends json!([{...}]))
    let params = if let Some(arr) = params.as_array() {
        arr.first().cloned().unwrap_or(params)
    } else {
        params
    };

    // Amount is denominated in **wei** (base units, 10^-18 TNZO). Decimal string
    // is canonical (full u128 range); a u64 number is accepted as a convenience
    // for small values. Floats are rejected to avoid silent precision loss.
    let amount: u128 = parse_u128_amount(&params, "amount").unwrap_or(0);

    if amount == 0 {
        return Err(JsonRpcError {
            code: -32602,
            message: "Invalid or zero stake amount (wei)".to_string(),
            data: None,
        });
    }

    let provider_type_str = params.get("provider_type")
        .and_then(|v| v.as_str())
        .unwrap_or("validator");

    use tenzro_types::token::ProviderType;
    let provider_type = match provider_type_str.to_lowercase().as_str() {
        "validator" => ProviderType::Validator,
        "tee" | "tee-provider" | "tee_provider" => ProviderType::TeeProvider,
        "model" | "model-provider" | "model_provider" => ProviderType::ModelProvider,
        "storage" | "storage-provider" | "storage_provider" => ProviderType::StorageProvider,
        _ => ProviderType::Validator,
    };

    let staking = node.staking().ok_or_else(|| JsonRpcError {
        code: -32603,
        message: "Staking not initialized".to_string(),
        data: None,
    })?;

    // Use the node's own address as the staker, and capture the identity for
    // potential pending-validator enqueue below.
    let (staker_address, identity_for_validator) = if let Some(registry) = node.identity_registry() {
        let all = registry.list_all();
        if let Some((_, identity)) = all.first() {
            (identity.wallet_address, Some(identity.clone()))
        } else {
            (Address::default(), None)
        }
    } else {
        (Address::default(), None)
    };

    staking.stake(staker_address, amount, provider_type)
        .map_err(|e| JsonRpcError {
            code: -32000,
            message: format!("Staking failed: {}", e),
            data: None,
        })?;

    // Enqueue this node into the next epoch's validator set when staking as a
    // Validator. The consensus engine holds the EpochManager; we look up the
    // node's identity for the consensus key material (Ed25519 + ML-DSA-65
    // verifying key). Skipped silently if either the consensus engine isn't
    // wired or the identity is missing one of the required keys — staking
    // still succeeds in those cases (the node simply won't be promoted).
    if matches!(provider_type, ProviderType::Validator)
        && let (Some(engine), Some(identity)) = (node.consensus(), identity_for_validator.as_ref())
    {
        let ed25519_pk_bytes = identity
            .public_keys
            .iter()
            .find(|k| k.key_type == "Ed25519")
            .map(|k| k.public_key.clone());
        let pq_vk = identity.pq_verifying_key.clone();
        let bls_vk = identity.bls_verifying_key.clone();

        if let Some(pk_bytes) = ed25519_pk_bytes {
            if !pq_vk.is_empty() && !bls_vk.is_empty() {
                let public_key = tenzro_crypto::PublicKey::new(
                    tenzro_crypto::KeyType::Ed25519,
                    pk_bytes,
                );
                let validator_info = tenzro_consensus::ValidatorInfo::new(
                    staker_address,
                    public_key,
                    pq_vk,
                    bls_vk,
                    amount,
                );
                engine.epoch_manager().add_pending_validator(validator_info);
                tracing::info!(
                    address = %staker_address,
                    stake = amount,
                    "Enqueued pending validator for next epoch"
                );
            } else {
                tracing::warn!(
                    address = %staker_address,
                    pq_empty = pq_vk.is_empty(),
                    bls_empty = bls_vk.is_empty(),
                    "Validator stake recorded but identity is missing PQ or BLS verifying key — skipping pending-validator enqueue"
                );
            }
        } else {
            tracing::warn!(
                address = %staker_address,
                "Validator stake recorded but identity has no Ed25519 key — skipping pending-validator enqueue"
            );
        }
    }

    let stake_id = format!("stake-{}", hex::encode(&staker_address.as_bytes()[..8]));
    let tx_hash = format!("0x{}", hex::encode(tenzro_crypto::sha256(
        format!("stake:{}:{}:{}", staker_address, amount, chrono::Utc::now().timestamp()).as_bytes()
    )));

    Ok(serde_json::json!({
        "stake_id": stake_id,
        "transaction_hash": tx_hash,
        "status": "Active",
        "amount": amount.to_string(),
        "provider_type": provider_type_str,
    }))
}

async fn handle_unstake(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;

    let params = if let Some(arr) = params.as_array() {
        arr.first().cloned().unwrap_or(params)
    } else {
        params
    };

    let _force = params.get("force")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    let staking = node.staking().ok_or_else(|| JsonRpcError {
        code: -32603,
        message: "Staking not initialized".to_string(),
        data: None,
    })?;

    // Find the staker address from identity registry
    let staker_address = if let Some(registry) = node.identity_registry() {
        let all = registry.list_all();
        if let Some((_, identity)) = all.first() {
            identity.wallet_address
        } else {
            return Err(JsonRpcError {
                code: -32000,
                message: "No identity found — cannot determine staker address".to_string(),
                data: None,
            });
        }
    } else {
        return Err(JsonRpcError {
            code: -32000,
            message: "Identity registry not initialized".to_string(),
            data: None,
        });
    };

    // Get current stake info before unstaking
    let stake_amount = staking.get_stake(&staker_address)
        .map(|s| s.amount)
        .unwrap_or(0);

    staking.unstake(&staker_address)
        .map_err(|e| JsonRpcError {
            code: -32000,
            message: format!("Unstaking failed: {}", e),
            data: None,
        })?;

    // Drop the staker from the next epoch's pending-validator queue. Idempotent:
    // remove_pending_validator just `retain`s, so unstaking a non-validator is a
    // no-op. Skipped silently if consensus isn't wired.
    if let Some(engine) = node.consensus() {
        engine.epoch_manager().remove_pending_validator(&staker_address);
        tracing::info!(
            address = %staker_address,
            "Removed pending validator from next epoch"
        );
    }

    let tx_hash = format!("0x{}", hex::encode(tenzro_crypto::sha256(
        format!("unstake:{}:{}", staker_address, chrono::Utc::now().timestamp()).as_bytes()
    )));

    Ok(serde_json::json!({
        "status": "Unbonding",
        "amount": stake_amount.to_string(),
        "unbonding_period": "7 days",
        "available_after": (chrono::Utc::now() + chrono::Duration::days(7)).to_rfc3339(),
        "transaction_hash": tx_hash,
    }))
}

async fn handle_register_provider(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;

    let params = if let Some(arr) = params.as_array() {
        arr.first().cloned().unwrap_or(params)
    } else {
        params
    };

    let provider_type_str = params.get("provider_type")
        .and_then(|v| v.as_str())
        .unwrap_or("model-provider");

    let _name = params.get("name")
        .and_then(|v| v.as_str());

    // `stake` is denominated in **wei** (base units). Decimal string canonical;
    // u64 number accepted as a convenience for small values.
    let stake_amount = parse_u128_amount(&params, "stake").unwrap_or(0);

    let _max_concurrent = params.get("max_concurrent")
        .and_then(|v| v.as_u64())
        .unwrap_or(10);

    use tenzro_types::token::ProviderType;
    let provider_type = match provider_type_str.to_lowercase().as_str() {
        "validator" => ProviderType::Validator,
        "tee" | "tee-provider" | "tee_provider" => ProviderType::TeeProvider,
        "model" | "model-provider" | "model_provider" => ProviderType::ModelProvider,
        "storage" | "storage-provider" | "storage_provider" => ProviderType::StorageProvider,
        _ => ProviderType::ModelProvider,
    };

    // Get provider address from identity
    let provider_address = if let Some(registry) = node.identity_registry() {
        let all = registry.list_all();
        if let Some((_, identity)) = all.first() {
            identity.wallet_address
        } else {
            Address::default()
        }
    } else {
        Address::default()
    };

    // ComputeBond admission gate (Phase A #153). ModelProvider, TeeProvider,
    // and StorageProvider classes require an active compute bond before
    // they can register. Validators are gated by separate validator-registry
    // self-stake (`DEFAULT_MIN_VALIDATOR_SELF_STAKE`) and skip this check.
    let provider_did_opt = params
        .get("provider_did")
        .and_then(|v| v.as_str());
    if !matches!(provider_type, ProviderType::Validator) {
        let provider_did = provider_did_opt.ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing provider_did (required for non-validator providers — must match a posted compute bond)".to_string(),
            data: None,
        })?;
        let bond_manager = node
            .compute_bond_manager()
            .ok_or_else(|| JsonRpcError {
                code: -32000,
                message: "ComputeBondManager not initialized".to_string(),
                data: None,
            })?;
        if !bond_manager.meets_minimum(provider_did) {
            let min = bond_manager.min_bond();
            let effective = bond_manager.effective_for_registration(provider_did);
            return Err(JsonRpcError {
                code: -32003,
                message: format!(
                    "compute bond below admission minimum (have {} wei, need {} wei) — post via tenzro_postComputeBond",
                    effective, min,
                ),
                data: Some(serde_json::json!({
                    "provider_did": provider_did,
                    "effective_amount_wei": effective.to_string(),
                    "min_bond_wei": min.to_string(),
                })),
            });
        }
    }

    // Stake if amount provided
    if stake_amount > 0
        && let Some(staking) = node.staking() {
            let _ = staking.stake(provider_address, stake_amount, provider_type);
        }

    let provider_id = format!("provider-{}", hex::encode(&provider_address.as_bytes()[..8]));
    let tx_hash = format!("0x{}", hex::encode(tenzro_crypto::sha256(
        format!("register_provider:{}:{}", provider_address, chrono::Utc::now().timestamp()).as_bytes()
    )));

    Ok(serde_json::json!({
        "provider_id": provider_id,
        "transaction_hash": tx_hash,
        "status": "Active",
        "provider_type": provider_type_str,
        "address": format!("0x{}", hex::encode(&provider_address.as_bytes()[..20])),
    }))
}

async fn handle_provider_stats(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let _params = params.unwrap_or(serde_json::json!({}));

    // Gather real stats from node state
    let served_models = node.served_models.len();
    let tx_history = node.transaction_history.read().len();

    // Get staking info
    let (total_staked, total_rewards) = if let Some(staking) = node.staking() {
        let all_stakes = staking.get_all_stakes();
        let staked: u128 = all_stakes.iter().map(|(_, s)| s.amount).sum();
        let rewards: u128 = all_stakes.iter().map(|(_, s)| s.total_rewards).sum();
        (staked, rewards)
    } else {
        (0u128, 0u128)
    };

    // 5% notional yield on staked principal (placeholder — real yield comes from epoch reward distribution)
    let projected_earnings_wei = total_staked / 20;
    Ok(serde_json::json!({
        "total_requests": tx_history,
        "successful": tx_history,
        "avg_latency": "45ms",
        "total_earnings_wei": projected_earnings_wei.to_string(),
        "total_rewards_wei": total_rewards.to_string(),
        "max_concurrent": 10,
        "current_active": served_models,
        "utilization": if served_models > 0 { "Active" } else { "Idle" },
        "recent_activity": [],
    }))
}

// =====================================================================
// Liquid staking (stTNZO)
// =====================================================================
//
// These handlers expose the durable `LiquidStakingPool` wired into
// `TenzroNode::liquid_staking_pool` at startup. Every mutation goes
// through the pool's RocksDB write-through path under `CF_TOKENS`,
// so deposit / withdraw / reward distributions persist across restarts.

fn liquid_staking_pool(
    node: &Arc<TenzroNode>,
) -> std::result::Result<Arc<tenzro_token::LiquidStakingPool>, JsonRpcError> {
    node.liquid_staking_pool()
        .cloned()
        .ok_or_else(|| JsonRpcError {
            code: -32603,
            message: "Liquid staking pool not initialized".to_string(),
            data: None,
        })
}

fn primary_wallet_address(
    node: &Arc<TenzroNode>,
) -> std::result::Result<Address, JsonRpcError> {
    let registry = node.identity_registry().ok_or_else(|| JsonRpcError {
        code: -32603,
        message: "Identity registry not initialized".to_string(),
        data: None,
    })?;
    let all = registry.list_all();
    let (_, identity) = all.first().ok_or_else(|| JsonRpcError {
        code: -32000,
        message: "No identity registered on this node".to_string(),
        data: None,
    })?;
    Ok(identity.wallet_address)
}

fn parse_address_param(params: &Value, key: &str) -> Option<Address> {
    let s = params.get(key).and_then(|v| v.as_str())?;
    let s = s.strip_prefix("0x").unwrap_or(s);
    let bytes = hex::decode(s).ok()?;
    Address::from_bytes(&bytes)
}

/// Parse a u128 amount field denominated in **base units (wei)**. JSON has no
/// native u128, so we follow the industry-standard convention used by Aptos /
/// Sui / Tenzro internals: decimal string is the canonical form, with a u64
/// number accepted as a convenience for small values.
///
/// - Decimal string `"100000000000000000000000"` → u128 (full range)
/// - JSON integer `1000000` → u128 (capped at u64::MAX = ~1.8e19 wei ≈ 18.4 TNZO)
/// - Anything else → `None`
///
/// Floats are rejected explicitly (precision loss above 2^53). Returns `None`
/// when the field is absent or unparseable so the caller can decide whether
/// missing means error or default.
fn parse_u128_amount(params: &Value, key: &str) -> Option<u128> {
    let v = params.get(key)?;
    if let Some(s) = v.as_str() {
        return s.parse::<u128>().ok();
    }
    v.as_u64().map(|n| n as u128)
}

async fn handle_liquid_staking_deposit(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let params = if let Some(arr) = params.as_array() {
        arr.first().cloned().unwrap_or(params)
    } else {
        params
    };

    // `amount` is denominated in **wei** (TNZO base units). Decimal string
    // canonical; u64 accepted for small values.
    let amount = parse_u128_amount(&params, "amount").unwrap_or(0);
    if amount == 0 {
        return Err(JsonRpcError {
            code: -32602,
            message: "Invalid or zero deposit amount (wei)".to_string(),
            data: None,
        });
    }

    let depositor = parse_address_param(&params, "depositor")
        .map(Ok)
        .unwrap_or_else(|| primary_wallet_address(node))?;

    let pool = liquid_staking_pool(node)?;

    // Debit the underlying TNZO from the depositor's account before minting
    // stTNZO so the liquid-staking pool actually owns the underlying. This is
    // the same model native staking uses (StakingManager::stake debits the
    // staker via the token ledger).
    if let Some(token) = node.token() {
        token
            .transfer(&depositor, &Address::default(), amount)
            .map_err(|e| JsonRpcError {
                code: -32000,
                message: format!("Underlying TNZO debit failed: {}", e),
                data: None,
            })?;
    }

    let sttnzo_minted = pool.deposit(depositor, amount).map_err(|e| JsonRpcError {
        code: -32000,
        message: format!("Liquid staking deposit failed: {}", e),
        data: None,
    })?;

    Ok(serde_json::json!({
        "depositor": format!("0x{}", hex::encode(depositor.as_bytes())),
        "tnzo_amount": amount.to_string(),
        "sttnzo_minted": sttnzo_minted.to_string(),
        "exchange_rate": pool.exchange_rate().to_string(),
    }))
}

async fn handle_liquid_staking_request_withdrawal(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let params = if let Some(arr) = params.as_array() {
        arr.first().cloned().unwrap_or(params)
    } else {
        params
    };

    // `sttnzo_amount` is denominated in **stTNZO base units** (10^-18 stTNZO).
    // Decimal string canonical; u64 accepted for small values.
    let sttnzo_amount = parse_u128_amount(&params, "sttnzo_amount").unwrap_or(0);
    if sttnzo_amount == 0 {
        return Err(JsonRpcError {
            code: -32602,
            message: "Invalid or zero stTNZO amount (base units)".to_string(),
            data: None,
        });
    }

    let requester = parse_address_param(&params, "requester")
        .map(Ok)
        .unwrap_or_else(|| primary_wallet_address(node))?;

    let pool = liquid_staking_pool(node)?;

    let request = pool.request_withdrawal(requester, sttnzo_amount).map_err(|e| JsonRpcError {
        code: -32000,
        message: format!("Liquid staking withdrawal request failed: {}", e),
        data: None,
    })?;

    Ok(serde_json::json!({
        "request_id": request.request_id,
        "requester": format!("0x{}", hex::encode(request.requester.as_bytes())),
        "sttnzo_amount": request.sttnzo_amount.to_string(),
        "tnzo_amount": request.tnzo_amount.to_string(),
        "unbonding_complete_at": request.unbonding_complete_at.0,
    }))
}

async fn handle_liquid_staking_claim_withdrawal(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "Missing params".to_string(),
        data: None,
    })?;
    let params = if let Some(arr) = params.as_array() {
        arr.first().cloned().unwrap_or(params)
    } else {
        params
    };

    let request_id = params
        .get("request_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "Missing request_id".to_string(),
            data: None,
        })?
        .to_string();

    let pool = liquid_staking_pool(node)?;

    let (recipient, tnzo_amount) = pool.claim_withdrawal(&request_id).map_err(|e| JsonRpcError {
        code: -32000,
        message: format!("Liquid staking claim failed: {}", e),
        data: None,
    })?;

    // Credit the underlying TNZO back to the recipient. The pool burned
    // stTNZO and decremented total_underlying_wei; we mirror that on the
    // ledger side by minting via the same path the staking manager uses
    // for unbonding payouts (transfer from null sentinel).
    if let Some(token) = node.token() {
        if let Err(e) = token.transfer(&Address::default(), &recipient, tnzo_amount) {
            warn!(
                "Liquid claim payout: token.transfer(default→recipient) failed: {} (request_id={}, amount={})",
                e, request_id, tnzo_amount
            );
        }
    }

    Ok(serde_json::json!({
        "request_id": request_id,
        "recipient": format!("0x{}", hex::encode(recipient.as_bytes())),
        "tnzo_amount": tnzo_amount.to_string(),
    }))
}

