async fn handle_encode_function(
    _node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = unwrap_params(params)?;

    let function_sig = params.get("function_sig").and_then(|v| v.as_str()).ok_or_else(|| JsonRpcError {
        code: -32602, message: "Missing function_sig (e.g. 'transfer(address,uint256)')".to_string(), data: None,
    })?;
    let args: Vec<String> = params.get("args")
        .and_then(|v| v.as_array())
        .map(|arr| arr.iter().filter_map(|v| v.as_str().map(String::from)).collect())
        .unwrap_or_default();

    // Compute function selector: keccak256(function_sig)[0..4]
    let sig_hash = tenzro_crypto::hash::keccak256(function_sig.as_bytes());
    let selector = &sig_hash.as_bytes()[..4];

    // ABI encode arguments (simplified: each arg is zero-padded to 32 bytes)
    let mut encoded = selector.to_vec();
    for arg in &args {
        let arg_clean = arg.strip_prefix("0x").unwrap_or(arg);

        if arg_clean.len() <= 64 {
            // Treat as hex-encoded value, left-pad to 32 bytes
            let arg_bytes = hex::decode(arg_clean).unwrap_or_else(|_| {
                // If not hex, treat as decimal number
                if let Ok(num) = arg_clean.parse::<u128>() {
                    let mut buf = [0u8; 32];
                    buf[16..32].copy_from_slice(&num.to_be_bytes());
                    buf.to_vec()
                } else {
                    // UTF-8 string fallback
                    arg_clean.as_bytes().to_vec()
                }
            });
            let mut padded = vec![0u8; 32];
            let start = 32usize.saturating_sub(arg_bytes.len());
            let copy_len = arg_bytes.len().min(32);
            padded[start..start + copy_len].copy_from_slice(&arg_bytes[..copy_len]);
            encoded.extend_from_slice(&padded);
        } else {
            // Long hex value — take first 32 bytes
            let arg_bytes = hex::decode(arg_clean).map_err(|e| JsonRpcError {
                code: -32602, message: format!("Invalid hex argument: {}", e), data: None,
            })?;
            let mut padded = vec![0u8; 32];
            let copy_len = arg_bytes.len().min(32);
            padded[32 - copy_len..32].copy_from_slice(&arg_bytes[..copy_len]);
            encoded.extend_from_slice(&padded);
        }
    }

    Ok(serde_json::json!({
        "encoded_hex": format!("0x{}", hex::encode(&encoded)),
        "function_selector": format!("0x{}", hex::encode(selector)),
        "function_sig": function_sig,
        "args_count": args.len(),
    }))
}

async fn handle_decode_result(
    _node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = unwrap_params(params)?;

    let data_hex = params.get("data_hex").and_then(|v| v.as_str()).ok_or_else(|| JsonRpcError {
        code: -32602, message: "Missing data_hex".to_string(), data: None,
    })?;
    let output_types: Vec<String> = params.get("output_types")
        .and_then(|v| v.as_array())
        .map(|arr| arr.iter().filter_map(|v| v.as_str().map(String::from)).collect())
        .unwrap_or_default();

    let data = decode_hex_param(data_hex)?;

    // Decode ABI-encoded output: split into 32-byte words and interpret per type
    let mut decoded = Vec::new();
    let mut offset = 0;

    for (i, out_type) in output_types.iter().enumerate() {
        if offset + 32 > data.len() {
            break;
        }

        let word = &data[offset..offset + 32];
        let value = match out_type.as_str() {
            "uint256" | "uint128" | "uint64" | "uint32" | "uint8" => {
                // Read as big-endian unsigned integer
                let mut val = 0u128;
                for &b in &word[16..32] {
                    val = (val << 8) | b as u128;
                }
                serde_json::json!({ "index": i, "type": out_type, "value": val.to_string() })
            }
            "address" => {
                let addr = &word[12..32];
                serde_json::json!({ "index": i, "type": "address", "value": format!("0x{}", hex::encode(addr)) })
            }
            "bool" => {
                let val = word[31] != 0;
                serde_json::json!({ "index": i, "type": "bool", "value": val })
            }
            "bytes32" => {
                serde_json::json!({ "index": i, "type": "bytes32", "value": format!("0x{}", hex::encode(word)) })
            }
            _ => {
                serde_json::json!({ "index": i, "type": out_type, "value": format!("0x{}", hex::encode(word)) })
            }
        };
        decoded.push(value);
        offset += 32;
    }

    Ok(serde_json::json!({
        "decoded": decoded,
        "raw_data_hex": data_hex,
        "total_words": data.len() / 32,
    }))
}

// ============================================================================
// GROUP 7: Streaming handlers (2 methods)
// ============================================================================

async fn handle_chat_stream(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = unwrap_params(params)?;

    let model_id = params.get("model_id").or_else(|| params.get("model"))
        .and_then(|v| v.as_str()).ok_or_else(|| JsonRpcError {
        code: -32602, message: "Missing model_id".to_string(), data: None,
    })?;
    let message = params.get("message").or_else(|| params.get("content"))
        .and_then(|v| v.as_str()).ok_or_else(|| JsonRpcError {
        code: -32602, message: "Missing message".to_string(), data: None,
    })?;
    let max_tokens = params.get("max_tokens").and_then(|v| v.as_u64()).unwrap_or(1024) as usize;

    // Delegate to the existing chat handler logic (full result, streaming at transport level)
    let chat_params = serde_json::json!({
        "model_id": model_id,
        "message": message,
        "max_tokens": max_tokens,
    });

    handle_chat(node, Some(chat_params)).await.map(|result| {
        // Wrap result with streaming metadata
        serde_json::json!({
            "stream": true,
            "model_id": model_id,
            "result": result,
            "usage": {
                "prompt_tokens": message.split_whitespace().count(),
                "completion_tokens": result.get("response")
                    .and_then(|r| r.as_str())
                    .map(|s| s.split_whitespace().count())
                    .unwrap_or(0),
            },
        })
    })
}

async fn handle_subscribe_events_stream(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let params = params.map(|p| if let Some(arr) = p.as_array() { arr.first().cloned().unwrap_or(p) } else { p });

    let event_types: Vec<String> = params.as_ref()
        .and_then(|p| p.get("event_types"))
        .and_then(|v| v.as_array())
        .map(|arr| arr.iter().filter_map(|v| v.as_str().map(String::from)).collect())
        .unwrap_or_else(|| vec!["block".to_string(), "transaction".to_string()]);

    let from_block = params.as_ref()
        .and_then(|p| p.get("from_block")).and_then(|v| v.as_u64());

    let subscription_id = uuid::Uuid::new_v4().to_string();
    let status = node.status().await;

    // Store subscription in metadata
    let storage = node.storage().ok_or_else(|| JsonRpcError {
        code: -32000, message: "Storage not initialized".to_string(), data: None,
    })?;

    let subscription = serde_json::json!({
        "subscription_id": subscription_id,
        "event_types": event_types,
        "from_block": from_block.unwrap_or(status.block_height),
        "created_at": chrono::Utc::now().to_rfc3339(),
        "status": "active",
    });

    let key = format!("event_sub:{}", subscription_id);
    storage.put(tenzro_storage::CF_METADATA, key.as_bytes(), serde_json::to_vec(&subscription).unwrap().as_slice()).map_err(|e| JsonRpcError {
        code: -32603, message: format!("Failed to store subscription: {}", e), data: None,
    })?;

    Ok(serde_json::json!({
        "subscription_id": subscription_id,
        "event_types": event_types,
        "from_block": from_block.unwrap_or(status.block_height),
        "status": "active",
        "message": "Use SSE endpoint /events/{subscription_id} for real-time streaming",
    }))
}

// ============================================================================
// Tenzro Train RPC handlers
// ============================================================================
//
// Phase 1 scope: Open tier only, Mean aggregation, timeseries-first.
// The Rust protocol layer owns coordination/aggregation/settlement; the
// inner training loop is dispatched to the Python reference trainer at
// `integrations/trainer/`. See TRAIN.md §7.1 for the full split rationale.

/// Map a `TrainingError` to a JSON-RPC error.
fn training_err(e: tenzro_training::TrainingError) -> JsonRpcError {
    use tenzro_training::TrainingError as TE;
    let code = match &e {
        TE::TaskNotFound(_)
        | TE::InvalidTaskSpec(_)
        | TE::AlreadyEnrolled(_)
        | TE::EnrollmentClosed(_)
        | TE::InvalidRound { .. }
        | TE::FragmentOutOfRange { .. }
        | TE::DimensionMismatch(_)
        | TE::PayloadSizeMismatch { .. }
        | TE::PayloadHashMismatch
        | TE::AggregationRuleTierMismatch { .. }
        | TE::SealedManifestMissing { .. }
        | TE::SealedManifestHashMismatch { .. }
        | TE::SealedEnvelopeMissing { .. }
        | TE::SealedShardSizeMismatch { .. }
        | TE::SealedShardHashMismatch { .. }
        | TE::EnclaveBindingMismatch { .. }
        | TE::InvalidSignature { .. } => -32602,
        TE::AttestationRequired(_) | TE::QuorumNotMet { .. } => -32011,
        TE::ConflictingFinalize { .. } => -32010,
        TE::Aggregation(_) | TE::Storage(_) | TE::Serialization(_) | TE::Internal(_) => -32603,
    };
    JsonRpcError {
        code,
        message: e.to_string(),
        data: None,
    }
}

/// `tenzro_training_postTask`: register a new training run with the local
/// node acting as syncer. Phase 1 accepts the full TaskSpec inline as JSON.
///
/// Params: `{ task_spec: TrainingTaskSpec, syncer_did?: string, syncer_address?: hex }`
/// The syncer DID/address default to the node's primary identity if omitted.
async fn handle_training_post_task(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let p = params.ok_or_else(|| missing_param("params"))?;
    let task_spec_value = p
        .get("task_spec")
        .ok_or_else(|| missing_param("task_spec"))?;
    let task_spec: tenzro_types::training::TrainingTaskSpec =
        serde_json::from_value(task_spec_value.clone()).map_err(|e| JsonRpcError {
            code: -32602,
            message: format!("invalid task_spec: {}", e),
            data: None,
        })?;
    let syncer_did = p
        .get("syncer_did")
        .and_then(|v| v.as_str())
        .map(|s| s.to_string())
        .unwrap_or_else(|| format!("did:tenzro:machine:syncer-{}", task_spec.task_id));
    let syncer_address = match p.get("syncer_address").and_then(|v| v.as_str()) {
        Some(hex_str) => {
            let bytes = hex::decode(hex_str.trim_start_matches("0x")).map_err(|e| JsonRpcError {
                code: -32602,
                message: format!("invalid syncer_address hex: {}", e),
                data: None,
            })?;
            if bytes.len() != 32 {
                return Err(JsonRpcError {
                    code: -32602,
                    message: "syncer_address must be 32 bytes".to_string(),
                    data: None,
                });
            }
            let mut arr = [0u8; 32];
            arr.copy_from_slice(&bytes);
            Address::new(arr)
        }
        None => Address::new([0u8; 32]),
    };

    let task_id = task_spec.task_id.clone();
    let state = Arc::new(tenzro_training::SyncerState::new(
        task_spec,
        syncer_did,
        syncer_address,
    ));
    node.training_runtime
        .register_run(state)
        .map_err(training_err)?;

    Ok(serde_json::json!({
        "task_id": task_id,
        "status": "registered",
    }))
}

/// `tenzro_training_listRuns`: list all active training runs the node is syncing.
async fn handle_training_list_runs(
    node: &Arc<TenzroNode>,
) -> std::result::Result<Value, JsonRpcError> {
    let runs = node.training_runtime.list_runs();
    Ok(serde_json::json!({ "runs": runs }))
}

/// `tenzro_training_getRun`: look up a specific run by task_id.
async fn handle_training_get_run(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let p = params.ok_or_else(|| missing_param("params"))?;
    let task_id = p
        .get("task_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| missing_param("task_id"))?;
    match node.training_runtime.syncers.get(task_id) {
        Some(state) => {
            let run = state.run.read().clone();
            Ok(serde_json::to_value(run).map_err(|e| JsonRpcError {
                code: -32603,
                message: format!("serialize run: {}", e),
                data: None,
            })?)
        }
        None => Err(JsonRpcError {
            code: -32602,
            message: format!("training run '{}' not found", task_id),
            data: None,
        }),
    }
}

/// `tenzro_training_getReceipt`: look up a sealed training receipt by task_id.
async fn handle_training_get_receipt(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let p = params.ok_or_else(|| missing_param("params"))?;
    let task_id = p
        .get("task_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| missing_param("task_id"))?;
    let receipt = node
        .training_runtime
        .get_receipt(task_id)
        .map_err(training_err)?;
    match receipt {
        Some(r) => Ok(serde_json::to_value(r).map_err(|e| JsonRpcError {
            code: -32603,
            message: format!("serialize receipt: {}", e),
            data: None,
        })?),
        None => Ok(serde_json::Value::Null),
    }
}

/// `tenzro_training_enrollTrainer`: enroll a trainer DID into an active run.
///
/// Open/Verified tier callers can omit `attestation`, `enclave_pubkey`,
/// and `measurements_hex` — the Confidential-tier validator short-circuits
/// on tier. Confidential-tier callers MUST supply all three; the runtime
/// rejects enrollment if the attestation is missing, the trainer's DID is
/// absent from the sealed-shard manifest, or the trainer's enclave pubkey
/// / measurements don't match what the sponsor sealed to.
///
/// Params: `{ task_id, trainer_did, attestation?: TrainingAttestation,
///            enclave_pubkey?: hex, measurements_hex?: string }`
async fn handle_training_enroll_trainer(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let p = params.ok_or_else(|| missing_param("params"))?;
    let task_id = p
        .get("task_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| missing_param("task_id"))?
        .to_string();
    let trainer_did = p
        .get("trainer_did")
        .and_then(|v| v.as_str())
        .ok_or_else(|| missing_param("trainer_did"))?
        .to_string();
    let attestation: Option<tenzro_types::training::TrainingAttestation> = match p.get("attestation")
    {
        Some(Value::Null) | None => None,
        Some(v) => Some(serde_json::from_value(v.clone()).map_err(|e| JsonRpcError {
            code: -32602,
            message: format!("invalid attestation: {}", e),
            data: None,
        })?),
    };
    let enclave_pubkey: Vec<u8> = match p.get("enclave_pubkey").and_then(|v| v.as_str()) {
        Some(hex_str) => hex::decode(hex_str.trim_start_matches("0x")).map_err(|e| {
            JsonRpcError {
                code: -32602,
                message: format!("invalid enclave_pubkey hex: {}", e),
                data: None,
            }
        })?,
        None => Vec::new(),
    };
    let measurements_hex = p
        .get("measurements_hex")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .to_string();

    node.training_runtime
        .enroll_trainer(
            &task_id,
            trainer_did,
            attestation.as_ref(),
            &enclave_pubkey,
            &measurements_hex,
        )
        .map_err(training_err)?;

    let state = node
        .training_runtime
        .syncers
        .get(&task_id)
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: format!("training run '{}' not found", task_id),
            data: None,
        })?
        .clone();
    let run = state.run.read().clone();
    Ok(serde_json::json!({
        "task_id": task_id,
        "trainer_count": run.trainers.len(),
        "status": run.status.to_string(),
    }))
}

/// `tenzro_training_submitOuterGradient`: submit an outer gradient for the
/// current round. Caller is the trainer (or the trainer's local relay).
///
/// Params: `{ gradient: OuterGradient }`
async fn handle_training_submit_outer_gradient(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let p = params.ok_or_else(|| missing_param("params"))?;
    let gradient_value = p
        .get("gradient")
        .ok_or_else(|| missing_param("gradient"))?;
    let gradient: tenzro_types::training::OuterGradient =
        serde_json::from_value(gradient_value.clone()).map_err(|e| JsonRpcError {
            code: -32602,
            message: format!("invalid gradient: {}", e),
            data: None,
        })?;
    let task_id = gradient.task_id.clone();
    let state = node
        .training_runtime
        .syncers
        .get(&task_id)
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: format!("training run '{}' not found", task_id),
            data: None,
        })?
        .clone();
    let gradient_for_gossip = gradient.clone();
    state
        .accept_outer_gradient(gradient)
        .map_err(training_err)?;

    // Broadcast on `tenzro/training` so other syncers tracking this run
    // (failover candidates, neighbor regions) can ingest the gradient via
    // the same accept path. `accept_outer_gradient` dedups by `trainer_did`,
    // so re-receiving a self-published gradient on a node that's both the
    // publisher and a subscriber is a no-op.
    if let Some(network) = node.network() {
        match tenzro_training::encode_outer_gradient(&gradient_for_gossip) {
            Ok(bytes) => {
                let msg = tenzro_network::NetworkMessage::new(
                    tenzro_network::MessagePayload::Custom {
                        topic: tenzro_training::TRAINING_TOPIC.to_string(),
                        data: bytes,
                    },
                );
                if let Err(e) = network
                    .broadcast(tenzro_training::TRAINING_TOPIC, msg)
                    .await
                {
                    tracing::warn!(
                        %task_id,
                        error = %e,
                        "Failed to broadcast OuterGradient on tenzro/training"
                    );
                }
            }
            Err(e) => tracing::warn!(
                %task_id,
                error = %e,
                "Failed to bincode-encode OuterGradient for gossip"
            ),
        }
    }

    Ok(serde_json::json!({
        "task_id": task_id,
        "accepted": true,
    }))
}

/// `tenzro_training_finalizeRound`: advance the syncer to the next round
/// after collecting K-of-M for every fragment. Caller supplies the
/// post-aggregation parameter hashes (provided by the Python reference
/// trainer over its JSON-RPC bridge).
///
/// Params: `{ task_id, round, post_step_hashes: { "<fragment>": "<hex>" } }`
async fn handle_training_finalize_round(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let p = params.ok_or_else(|| missing_param("params"))?;
    let task_id = p
        .get("task_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| missing_param("task_id"))?
        .to_string();
    let round = p
        .get("round")
        .and_then(|v| v.as_u64())
        .ok_or_else(|| missing_param("round"))? as u32;
    let post_step_obj = p
        .get("post_step_hashes")
        .and_then(|v| v.as_object())
        .ok_or_else(|| missing_param("post_step_hashes"))?;
    let mut post_step_hashes = std::collections::HashMap::new();
    for (k, v) in post_step_obj {
        let frag: u32 = k.parse().map_err(|e| JsonRpcError {
            code: -32602,
            message: format!("invalid fragment index '{}': {}", k, e),
            data: None,
        })?;
        let hex_str = v.as_str().ok_or_else(|| JsonRpcError {
            code: -32602,
            message: format!("post_step_hashes['{}'] must be a hex string", k),
            data: None,
        })?;
        let bytes = hex::decode(hex_str.trim_start_matches("0x")).map_err(|e| JsonRpcError {
            code: -32602,
            message: format!("invalid hex for fragment {}: {}", frag, e),
            data: None,
        })?;
        let hash = Hash::from_bytes(&bytes).ok_or_else(|| JsonRpcError {
            code: -32602,
            message: format!("invalid hash for fragment {}: must be 32 bytes", frag),
            data: None,
        })?;
        post_step_hashes.insert(frag, hash);
    }
    let state = node
        .training_runtime
        .syncers
        .get(&task_id)
        .ok_or_else(|| JsonRpcError {
            code: -32602,
            message: format!("training run '{}' not found", task_id),
            data: None,
        })?
        .clone();
    let sync_round = state
        .build_sync_round(round, post_step_hashes)
        .map_err(training_err)?;
    state
        .finalize_round(round, sync_round.state_root)
        .map_err(training_err)?;
    node.training_runtime
        .persist_run(&state)
        .map_err(training_err)?;

    // Broadcast on `tenzro/training/syncer` so failover-candidate syncers
    // and any local trainer-side daemons can track the canonical state-root
    // chain without polling `tenzro_training_getRun`.
    if let Some(network) = node.network() {
        match tenzro_training::encode_sync_round(&sync_round) {
            Ok(bytes) => {
                let msg = tenzro_network::NetworkMessage::new(
                    tenzro_network::MessagePayload::Custom {
                        topic: tenzro_training::TRAINING_SYNCER_TOPIC.to_string(),
                        data: bytes,
                    },
                );
                if let Err(e) = network
                    .broadcast(tenzro_training::TRAINING_SYNCER_TOPIC, msg)
                    .await
                {
                    tracing::warn!(
                        %task_id,
                        round,
                        error = %e,
                        "Failed to broadcast SyncRound on tenzro/training/syncer"
                    );
                }
            }
            Err(e) => tracing::warn!(
                %task_id,
                round,
                error = %e,
                "Failed to bincode-encode SyncRound for gossip"
            ),
        }
    }

    serde_json::to_value(sync_round).map_err(|e| JsonRpcError {
        code: -32603,
        message: format!("serialize sync_round: {}", e),
        data: None,
    })
}

/// `tenzro_training_installSealedManifest`: bind a sponsor's sealed-shard
/// manifest to a Confidential-tier training run. The manifest hash is
/// recomputed canonically and checked against the task spec's
/// `dataset_ref` (`tee://<hex>`); on success the normalized manifest is
/// persisted under `manifest:<task_id>` in `CF_TRAINING_RUNS`.
///
/// Params: `{ manifest: SealedDatasetManifest }`
async fn handle_training_install_sealed_manifest(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let p = params.ok_or_else(|| missing_param("params"))?;
    let manifest_value = p
        .get("manifest")
        .ok_or_else(|| missing_param("manifest"))?;
    let manifest: tenzro_types::training::SealedDatasetManifest =
        serde_json::from_value(manifest_value.clone()).map_err(|e| JsonRpcError {
            code: -32602,
            message: format!("invalid manifest: {}", e),
            data: None,
        })?;
    let stored = node
        .training_runtime
        .install_sealed_manifest(manifest)
        .map_err(training_err)?;

    // Broadcast on `tenzro/training` so enrolled trainers in any region
    // learn about the binding without polling `tenzro_training_getSealedManifest`.
    // `install_sealed_manifest` is idempotent (hash-stamp + binding check),
    // so re-receiving the manifest on the publisher's own subscription is a
    // safe no-op. Phase B2 (#217): the manifest carries the SHA-256 hashes
    // for each shard ciphertext; trainers then fetch ciphertexts by hash via
    // the IrohSealedShardStore.
    if let Some(network) = node.network() {
        match tenzro_training::encode_install_sealed_manifest(stored.as_ref()) {
            Ok(bytes) => {
                let msg = tenzro_network::NetworkMessage::new(
                    tenzro_network::MessagePayload::Custom {
                        topic: tenzro_training::TRAINING_TOPIC.to_string(),
                        data: bytes,
                    },
                );
                if let Err(e) = network
                    .broadcast(tenzro_training::TRAINING_TOPIC, msg)
                    .await
                {
                    tracing::warn!(
                        task_id = %stored.task_id,
                        error = %e,
                        "Failed to broadcast SealedDatasetManifest on tenzro/training"
                    );
                }
            }
            Err(e) => tracing::warn!(
                task_id = %stored.task_id,
                error = %e,
                "Failed to bincode-encode SealedDatasetManifest for gossip"
            ),
        }
    }

    serde_json::to_value(stored.as_ref()).map_err(|e| JsonRpcError {
        code: -32603,
        message: format!("serialize manifest: {}", e),
        data: None,
    })
}

/// `tenzro_training_getSealedManifest`: look up a Confidential-tier task's
/// installed sealed-shard manifest by `task_id`. Returns `null` if no
/// manifest has been installed.
///
/// Params: `{ task_id }`
async fn handle_training_get_sealed_manifest(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let p = params.ok_or_else(|| missing_param("params"))?;
    let task_id = p
        .get("task_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| missing_param("task_id"))?;
    match node.training_runtime.manifests.get(task_id) {
        Some(m) => serde_json::to_value(m.as_ref()).map_err(|e| JsonRpcError {
            code: -32603,
            message: format!("serialize manifest: {}", e),
            data: None,
        }),
        None => Ok(Value::Null),
    }
}

// ============================================================================
// ERC-4337 v0.8 Account Abstraction RPC handlers (Phase B Thread 3c / #165)
// ============================================================================
//
// Bundler-facing JSON-RPC surface. The `EntryPoint` singleton is constructed
// in `node::Node::bootstrap_agent_templates` (alongside `aa_validator_registry`)
// and accessed via `node.aa_entry_point()`. UserOps are validated against the
// per-account ERC-7579 validator modules (DelegationScopeValidator and any
// future modules), executed through `MultiVmRuntime`, and gas-charged against
// the smart account's EVM balance directly (no separate deposit pool).
//
// Wire format mirrors the public ERC-4337 bundler API: hex-string fields,
// `0x` prefix, `verifyingContract` is the EntryPoint address. Hashes returned
// to clients are 0x-prefixed lowercase hex.

fn aa_entry_point_or_err(
    node: &Arc<TenzroNode>,
) -> std::result::Result<Arc<tenzro_vm::EntryPoint>, JsonRpcError> {
    node.aa_entry_point().cloned().ok_or_else(|| JsonRpcError {
        code: -32603,
        message: "EntryPoint not initialized (vm_runtime + identity stack required)"
            .to_string(),
        data: None,
    })
}

fn parse_hex_bytes(s: &str) -> std::result::Result<Vec<u8>, JsonRpcError> {
    let stripped = s.strip_prefix("0x").unwrap_or(s);
    if stripped.is_empty() {
        return Ok(Vec::new());
    }
    hex::decode(stripped).map_err(|e| JsonRpcError {
        code: -32602,
        message: format!("invalid hex: {e}"),
        data: None,
    })
}

fn parse_u64_field(v: &Value, field: &str) -> std::result::Result<u64, JsonRpcError> {
    parse_u64_value(v).ok_or_else(|| JsonRpcError {
        code: -32602,
        message: format!("invalid u64 field `{field}`"),
        data: None,
    })
}

fn parse_u128_field(v: &Value, field: &str) -> std::result::Result<u128, JsonRpcError> {
    if let Some(n) = v.as_u64() {
        return Ok(n as u128);
    }
    if let Some(s) = v.as_str() {
        let stripped = s.strip_prefix("0x").or_else(|| s.strip_prefix("0X"));
        if let Some(hex_str) = stripped {
            return u128::from_str_radix(hex_str, 16).map_err(|_| JsonRpcError {
                code: -32602,
                message: format!("invalid u128 hex field `{field}`"),
                data: None,
            });
        }
        return s.parse::<u128>().map_err(|_| JsonRpcError {
            code: -32602,
            message: format!("invalid u128 decimal field `{field}`"),
            data: None,
        });
    }
    Err(JsonRpcError {
        code: -32602,
        message: format!("missing u128 field `{field}`"),
        data: None,
    })
}

/// Parse a UserOperation JSON object (ERC-4337 v0.8 wire format) into the
/// in-memory `UserOperation` type. All hex fields are 0x-prefixed lowercase.
/// Optional fields default to empty bytes / zero.
fn parse_user_operation(
    obj: &Value,
) -> std::result::Result<tenzro_vm::UserOperation, JsonRpcError> {
    let get_str = |k: &str| -> std::result::Result<&str, JsonRpcError> {
        obj.get(k)
            .and_then(|v| v.as_str())
            .ok_or_else(|| JsonRpcError {
                code: -32602,
                message: format!("missing string field `{k}`"),
                data: None,
            })
    };

    let sender = parse_hex_bytes(get_str("sender")?)?;
    let nonce = obj
        .get("nonce")
        .map(|v| parse_u64_field(v, "nonce"))
        .transpose()?
        .unwrap_or(0);
    let factory = obj
        .get("factory")
        .and_then(|v| v.as_str())
        .map(parse_hex_bytes)
        .transpose()?
        .unwrap_or_default();
    let factory_data = obj
        .get("factoryData")
        .and_then(|v| v.as_str())
        .map(parse_hex_bytes)
        .transpose()?
        .unwrap_or_default();
    let call_data = parse_hex_bytes(get_str("callData")?)?;
    let call_gas_limit = parse_u64_field(
        obj.get("callGasLimit").ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "missing field `callGasLimit`".to_string(),
            data: None,
        })?,
        "callGasLimit",
    )?;
    let verification_gas_limit = parse_u64_field(
        obj.get("verificationGasLimit").ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "missing field `verificationGasLimit`".to_string(),
            data: None,
        })?,
        "verificationGasLimit",
    )?;
    let pre_verification_gas = parse_u64_field(
        obj.get("preVerificationGas").ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "missing field `preVerificationGas`".to_string(),
            data: None,
        })?,
        "preVerificationGas",
    )?;
    let max_fee_per_gas = parse_u128_field(
        obj.get("maxFeePerGas").ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "missing field `maxFeePerGas`".to_string(),
            data: None,
        })?,
        "maxFeePerGas",
    )?;
    let max_priority_fee_per_gas = parse_u128_field(
        obj.get("maxPriorityFeePerGas").ok_or_else(|| JsonRpcError {
            code: -32602,
            message: "missing field `maxPriorityFeePerGas`".to_string(),
            data: None,
        })?,
        "maxPriorityFeePerGas",
    )?;
    let paymaster = obj
        .get("paymaster")
        .and_then(|v| v.as_str())
        .map(parse_hex_bytes)
        .transpose()?
        .unwrap_or_default();
    let paymaster_verification_gas_limit = obj
        .get("paymasterVerificationGasLimit")
        .map(|v| parse_u64_field(v, "paymasterVerificationGasLimit"))
        .transpose()?
        .unwrap_or(0);
    let paymaster_post_op_gas_limit = obj
        .get("paymasterPostOpGasLimit")
        .map(|v| parse_u64_field(v, "paymasterPostOpGasLimit"))
        .transpose()?
        .unwrap_or(0);
    let paymaster_data = obj
        .get("paymasterData")
        .and_then(|v| v.as_str())
        .map(parse_hex_bytes)
        .transpose()?
        .unwrap_or_default();
    let signature = parse_hex_bytes(get_str("signature")?)?;

    Ok(tenzro_vm::UserOperation {
        sender,
        nonce,
        factory,
        factory_data,
        call_data,
        call_gas_limit,
        verification_gas_limit,
        pre_verification_gas,
        max_fee_per_gas,
        max_priority_fee_per_gas,
        paymaster,
        paymaster_verification_gas_limit,
        paymaster_post_op_gas_limit,
        paymaster_data,
        signature,
    })
}

/// `eth_sendUserOperation(userOp, entryPoint)` — submit a UserOperation for
/// validation + execution. Returns the userOpHash (0x-prefixed hex) on
/// success. The bundler API expects synchronous validation; execution and gas
/// settlement happen inline in `EntryPoint::handle_single_op` before this
/// returns. Receipts are persisted for later `eth_getUserOperationReceipt`
/// retrieval.
async fn handle_send_user_operation(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let entry_point = aa_entry_point_or_err(node)?;
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "missing params: [userOp, entryPoint]".to_string(),
        data: None,
    })?;
    let arr = params.as_array().ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "params must be array [userOp, entryPoint]".to_string(),
        data: None,
    })?;
    let user_op_value = arr.first().ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "missing userOp at params[0]".to_string(),
        data: None,
    })?;

    // The second positional `entryPoint` is informational — we run the
    // singleton; if the caller passed a different address, reject so they
    // know the target is wrong rather than silently routing elsewhere.
    if let Some(ep_str) = arr.get(1).and_then(|v| v.as_str()) {
        let want = parse_hex_bytes(ep_str)?;
        if !want.is_empty() && want != entry_point.address {
            return Err(JsonRpcError {
                code: -32602,
                message: format!(
                    "entryPoint mismatch: this node serves 0x{}",
                    hex::encode(&entry_point.address)
                ),
                data: None,
            });
        }
    }

    let op = parse_user_operation(user_op_value)?;
    let receipt = entry_point.handle_single_op(op).await;
    if !receipt.success {
        return Err(JsonRpcError {
            code: -32000,
            message: "UserOp execution failed".to_string(),
            data: Some(serde_json::json!({
                "userOpHash": format!("0x{}", hex::encode(&receipt.user_op_hash)),
                "gasUsed": receipt.gas_used,
            })),
        });
    }
    Ok(Value::String(format!(
        "0x{}",
        hex::encode(&receipt.user_op_hash)
    )))
}

/// `eth_estimateUserOperationGas(userOp, entryPoint)` — return suggested gas
/// limits without executing. Uses `EntryPoint::simulate_user_op` which runs
/// the validation pipeline (validators included) and reports the gas the
/// pre-operation phase will consume. Call/verification gas hints come back
/// from the input op (callers iterate; bundlers normally do this off-line).
async fn handle_estimate_user_operation_gas(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let entry_point = aa_entry_point_or_err(node)?;
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "missing params: [userOp, entryPoint]".to_string(),
        data: None,
    })?;
    let arr = params.as_array().ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "params must be array [userOp, entryPoint]".to_string(),
        data: None,
    })?;
    let user_op_value = arr.first().ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "missing userOp at params[0]".to_string(),
        data: None,
    })?;
    let op = parse_user_operation(user_op_value)?;

    let sim = entry_point.simulate_user_op(&op).map_err(|e| JsonRpcError {
        code: -32000,
        message: format!("simulation failed: {e}"),
        data: None,
    })?;

    Ok(serde_json::json!({
        "preVerificationGas": format!("0x{:x}", op.pre_verification_gas),
        "verificationGasLimit": format!("0x{:x}", op.verification_gas_limit),
        "callGasLimit": format!("0x{:x}", op.call_gas_limit),
        "paid": format!("0x{:x}", sim.paid),
        "valid": sim.valid,
    }))
}

/// `eth_getUserOperationReceipt(userOpHash)` — return the persisted receipt
/// or null if the op was never seen by this node. Receipts are written under
/// `aa/receipt/<hex>` in `CF_AGENTS` and survive node restarts.
async fn handle_get_user_operation_receipt(
    node: &Arc<TenzroNode>,
    params: Option<Value>,
) -> std::result::Result<Value, JsonRpcError> {
    let entry_point = aa_entry_point_or_err(node)?;
    let params = params.ok_or_else(|| JsonRpcError {
        code: -32602,
        message: "missing params: [userOpHash]".to_string(),
        data: None,
    })?;
    let hash_str = if let Some(arr) = params.as_array() {
        arr.first().and_then(|v| v.as_str()).unwrap_or("")
    } else {
        params.as_str().unwrap_or("")
    };
    if hash_str.is_empty() {
        return Err(JsonRpcError {
            code: -32602,
            message: "missing userOpHash".to_string(),
            data: None,
        });
    }
    let hash_bytes = parse_hex_bytes(hash_str)?;
    let Some(receipt) = entry_point.get_receipt(&hash_bytes) else {
        return Ok(Value::Null);
    };
    Ok(serde_json::json!({
        "userOpHash": format!("0x{}", hex::encode(&receipt.user_op_hash)),
        "entryPoint": format!("0x{}", hex::encode(&entry_point.address)),
        "success": receipt.success,
        "actualGasUsed": format!("0x{:x}", receipt.gas_used),
        "actualGasCost": format!("0x{:x}", receipt.actual_gas_cost),
        "logs": receipt.logs.iter().map(|l| format!("0x{}", hex::encode(l))).collect::<Vec<_>>(),
    }))
}

/// `eth_supportedEntryPoints()` — return the list of EntryPoint addresses
/// served by this node. Currently a single v0.8 EntryPoint per node.
async fn handle_supported_entry_points(
    node: &Arc<TenzroNode>,
) -> std::result::Result<Value, JsonRpcError> {
    let entry_point = aa_entry_point_or_err(node)?;
    Ok(Value::Array(vec![Value::String(format!(
        "0x{}",
        hex::encode(&entry_point.address)
    ))]))
}

#[cfg(test)]
mod rich_chat_rpc_tests {
    use super::*;
    use tenzro_types::model::StopReason;

    // ── tool name validation (spec rule ^[a-zA-Z0-9_-]{1,64}$) ────────

    #[test]
    fn tool_name_accepts_alphanumeric_underscore_hyphen() {
        assert!(is_valid_tool_name("get_price"));
        assert!(is_valid_tool_name("GetPrice"));
        assert!(is_valid_tool_name("get-price"));
        assert!(is_valid_tool_name("a"));
        assert!(is_valid_tool_name("tool_42"));
        assert!(is_valid_tool_name("camelCase_with-dash_42"));
    }

    #[test]
    fn tool_name_rejects_empty() {
        assert!(!is_valid_tool_name(""));
    }

    #[test]
    fn tool_name_rejects_too_long() {
        let s: String = std::iter::repeat_n('a', 65).collect();
        assert!(!is_valid_tool_name(&s));
        let s64: String = std::iter::repeat_n('a', 64).collect();
        assert!(is_valid_tool_name(&s64));
    }

    #[test]
    fn tool_name_rejects_invalid_chars() {
        assert!(!is_valid_tool_name("get price"));   // space
        assert!(!is_valid_tool_name("get.price"));   // dot
        assert!(!is_valid_tool_name("get/price"));   // slash
        assert!(!is_valid_tool_name("get:price"));   // colon
        assert!(!is_valid_tool_name("get@price"));   // at
        assert!(!is_valid_tool_name("emoji😀"));     // non-ascii
    }

    // ── stop_reason mapping ───────────────────────────────────────────

    #[test]
    fn stop_reason_maps_known_values() {
        assert_eq!(map_stop_reason("tool_use"), StopReason::ToolUse);
        assert_eq!(map_stop_reason("max_tokens"), StopReason::MaxTokens);
        assert_eq!(map_stop_reason("stop_sequence"), StopReason::StopSequence);
        assert_eq!(map_stop_reason("end_turn"), StopReason::EndTurn);
    }

    #[test]
    fn stop_reason_unknown_falls_back_to_end_turn() {
        assert_eq!(map_stop_reason(""), StopReason::EndTurn);
        assert_eq!(map_stop_reason("unknown"), StopReason::EndTurn);
        assert_eq!(map_stop_reason("ERROR"), StopReason::EndTurn);
    }

    // ── shape dispatch (handle_chat routing) ──────────────────────────
    //
    // We don't spin up a node here; we just check the structural rule
    // baked into `handle_chat`: presence of `messages` vs `message`
    // determines the shape, both/neither is an error.
    //
    // The actual routing decision is encoded as a lookup table; tests
    // mirror the truth table at lines 5743–5758 of rpc.rs.

    #[test]
    fn shape_dispatch_truth_table() {
        // (has_messages, has_message) -> outcome label
        let outcome = |hm: bool, hs: bool| -> &'static str {
            match (hm, hs) {
                (true, true) => "error_both",
                (true, false) => "rich",
                (false, true) => "simple",
                (false, false) => "error_neither",
            }
        };
        assert_eq!(outcome(true, true), "error_both");
        assert_eq!(outcome(true, false), "rich");
        assert_eq!(outcome(false, true), "simple");
        assert_eq!(outcome(false, false), "error_neither");
    }

    // ── ContentBlock dispatch from runtime result ─────────────────────

    #[test]
    fn content_blocks_built_from_runtime_result() {
        use tenzro_model::ToolCall;
        use tenzro_types::model::ContentBlock;

        // Simulates the block-building loop in handle_chat_rich /
        // handle_chat_stream_rich: free text first, then each tool_use.
        let text = "Let me check the price.".to_string();
        let tool_calls = vec![ToolCall {
            id: "tu_01".to_string(),
            name: "get_price".to_string(),
            input: serde_json::json!({"pair": "TNZO/USD"}),
        }];

        let mut blocks: Vec<ContentBlock> = Vec::new();
        if !text.trim().is_empty() {
            blocks.push(ContentBlock::Text {
                text: text.clone(),
                cache_control: None,
            });
        }
        for tc in &tool_calls {
            blocks.push(ContentBlock::ToolUse {
                id: tc.id.clone(),
                name: tc.name.clone(),
                input: tc.input.clone(),
            });
        }

        assert_eq!(blocks.len(), 2);
        assert!(matches!(blocks[0], ContentBlock::Text { .. }));
        assert!(matches!(blocks[1], ContentBlock::ToolUse { .. }));
    }

    #[test]
    fn empty_response_yields_empty_text_block() {
        // The streaming path emits an empty text block when the model
        // produces neither text nor tool calls — gives the client a
        // well-formed envelope to close.
        use tenzro_types::model::ContentBlock;

        let text = "";
        let tool_calls: Vec<tenzro_model::ToolCall> = Vec::new();

        let mut blocks: Vec<ContentBlock> = Vec::new();
        if !text.trim().is_empty() {
            blocks.push(ContentBlock::Text {
                text: text.to_string(),
                cache_control: None,
            });
        }
        for tc in &tool_calls {
            blocks.push(ContentBlock::ToolUse {
                id: tc.id.clone(),
                name: tc.name.clone(),
                input: tc.input.clone(),
            });
        }
        if blocks.is_empty() {
            blocks.push(ContentBlock::Text {
                text: String::new(),
                cache_control: None,
            });
        }

        assert_eq!(blocks.len(), 1);
        match &blocks[0] {
            ContentBlock::Text { text, .. } => assert!(text.is_empty()),
            _ => panic!("expected text block"),
        }
    }

    // ── SSE event grammar shape (envelope correctness) ────────────────

    #[test]
    fn message_start_envelope_is_well_formed() {
        let payload = serde_json::json!({
            "id": "msg_01ABC",
            "model": "qwen3-8b",
            "role": "assistant",
            "content": [],
            "usage": { "input_tokens": 0, "output_tokens": 0 },
        });
        assert!(payload.get("id").is_some());
        assert_eq!(payload["role"], "assistant");
        assert_eq!(payload["content"].as_array().map(|a| a.len()), Some(0));
    }

    #[test]
    fn message_delta_envelope_carries_stop_reason_and_usage() {
        let payload = serde_json::json!({
            "delta": {
                "stop_reason": StopReason::ToolUse,
                "stop_sequence": serde_json::Value::Null,
            },
            "usage": { "input_tokens": 10, "output_tokens": 7 },
        });
        assert_eq!(payload["delta"]["stop_reason"], "tool_use");
        assert!(payload["delta"]["stop_sequence"].is_null());
        assert_eq!(payload["usage"]["output_tokens"], 7);
    }

    #[test]
    fn input_json_delta_carries_partial_json_string() {
        let input = serde_json::json!({"pair": "TNZO/USD"});
        let partial_json = serde_json::to_string(&input).unwrap();
        let delta = serde_json::json!({
            "index": 1,
            "delta": { "type": "input_json_delta", "partial_json": partial_json },
        });
        assert_eq!(delta["delta"]["type"], "input_json_delta");
        // partial_json is a JSON-encoded string, not a nested object.
        assert!(delta["delta"]["partial_json"].is_string());
        assert!(delta["delta"]["partial_json"].as_str().unwrap().contains("TNZO/USD"));
    }
}

#[cfg(test)]
mod params_normalization_tests {
    use super::*;

    #[test]
    fn unwraps_single_object_array_into_named_params() {
        // SDK pattern: json!([{"name": "alice", "creator": "0x..."}])
        let positional = serde_json::json!([{"name": "alice", "creator": "0x01"}]);
        let normalized = normalize_params(Some(positional)).unwrap();
        assert_eq!(normalized.get("name").and_then(|v| v.as_str()), Some("alice"));
        assert_eq!(normalized.get("creator").and_then(|v| v.as_str()), Some("0x01"));
    }

    #[test]
    fn passes_through_named_params_unchanged() {
        let named = serde_json::json!({"name": "bob", "amount": 42});
        let normalized = normalize_params(Some(named.clone())).unwrap();
        assert_eq!(normalized, named);
    }

    #[test]
    fn passes_through_none_unchanged() {
        assert!(normalize_params(None).is_none());
    }

    #[test]
    fn passes_through_empty_array_unchanged() {
        let arr = serde_json::json!([]);
        let normalized = normalize_params(Some(arr.clone())).unwrap();
        assert_eq!(normalized, arr);
    }

    #[test]
    fn passes_through_multi_element_array_unchanged() {
        // Some EVM-compat handlers explicitly read `params.as_array()` for multi-arg
        // positional calls (e.g. eth_getBlockByNumber takes ["0x123", false]).
        // Multi-element arrays must NOT be unwrapped.
        let arr = serde_json::json!(["0x123", false]);
        let normalized = normalize_params(Some(arr.clone())).unwrap();
        assert_eq!(normalized, arr);
    }

    #[test]
    fn passes_through_single_scalar_array_unchanged() {
        // Single positional address: ["0xabc..."] should stay an array
        // because handlers like handle_get_balance read arr.first().as_str().
        let arr = serde_json::json!(["0xabc"]);
        let normalized = normalize_params(Some(arr.clone())).unwrap();
        assert_eq!(normalized, arr);
    }
}

#[cfg(test)]
mod onnx_runtime_rpc_tests {
    use super::*;

    // ── normalization key parsing ─────────────────────────────────────

    #[test]
    fn parse_normalization_clip_default() {
        let n = parse_normalization(None);
        assert_eq!(n.mean, ImageNormalization::CLIP.mean);
    }

    #[test]
    fn parse_normalization_keys() {
        assert_eq!(
            parse_normalization(Some("clip")).mean,
            ImageNormalization::CLIP.mean,
        );
        assert_eq!(
            parse_normalization(Some("imagenet")).mean,
            ImageNormalization::IMAGENET.mean,
        );
        assert_eq!(
            parse_normalization(Some("siglip")).mean,
            ImageNormalization::SIGLIP.mean,
        );
        // Unknown keys fall back to CLIP.
        assert_eq!(
            parse_normalization(Some("garbage")).mean,
            ImageNormalization::CLIP.mean,
        );
        // Case-insensitive.
        assert_eq!(
            parse_normalization(Some("ImageNet")).mean,
            ImageNormalization::IMAGENET.mean,
        );
    }

    // ── ModelError → JsonRpcError mapping ─────────────────────────────

    #[test]
    fn forecast_err_maps_model_not_found() {
        let e = forecast_err(tenzro_model::ModelError::ModelNotFound("x".into()));
        assert_eq!(e.code, -32004);
    }

    #[test]
    fn forecast_err_maps_provider_not_available() {
        let e = forecast_err(tenzro_model::ModelError::ProviderNotAvailable("x".into()));
        assert_eq!(e.code, -32011);
    }

    #[test]
    fn forecast_err_maps_invalid_model() {
        let e = forecast_err(tenzro_model::ModelError::InvalidModel("x".into()));
        assert_eq!(e.code, -32602);
    }

    #[test]
    fn forecast_err_maps_inference_error() {
        let e = forecast_err(tenzro_model::ModelError::InferenceError("x".into()));
        assert_eq!(e.code, -32010);
    }

    // ── catalog handler (no node state required) ──────────────────────

    #[tokio::test]
    async fn list_vision_catalog_returns_seven_models() {
        let r = handle_list_vision_catalog().await.unwrap();
        let models = r["models"].as_array().unwrap();
        assert!(models.len() >= 7);
    }

    // ── missing-param handling for handlers that only inspect Value ───

    #[test]
    fn missing_param_helper_returns_invalid_params_code() {
        let e = missing_param("model_id");
        assert_eq!(e.code, -32602);
        assert!(e.message.contains("model_id"));
    }

    // ── tenzro_getBlockRange: param parsing ───────────────────────────

    #[test]
    fn parse_u64_value_accepts_int_dec_hex() {
        use serde_json::json;
        assert_eq!(super::parse_u64_value(&json!(42u64)), Some(42));
        assert_eq!(super::parse_u64_value(&json!("42")), Some(42));
        assert_eq!(super::parse_u64_value(&json!("0x2a")), Some(42));
        assert_eq!(super::parse_u64_value(&json!("0X2A")), Some(42));
        assert_eq!(super::parse_u64_value(&json!("not a number")), None);
        assert_eq!(super::parse_u64_value(&json!(true)), None);
        assert_eq!(super::parse_u64_value(&json!(null)), None);
    }

    // Compile-time invariants: the runtime-enforced upper bound must never
    // exceed axum's default body limit window (we keep ~10x headroom).
    const _: () = assert!(super::BLOCK_RANGE_MAX <= 256);
    const _: () = assert!(super::BLOCK_RANGE_DEFAULT <= super::BLOCK_RANGE_MAX);
    const _: () = assert!(super::BLOCK_RANGE_DEFAULT > 0);
}

/// Unit tests for the ERC-7579 pre-sign gate that backs
/// `tenzro_signTransaction` (Task #25 self-custody runtime wiring).
///
/// The full `aa_pre_sign_check` helper takes an `&Arc<TenzroNode>`, which
/// is heavy to instantiate in a unit test. So these tests exercise the
/// pure pieces — `tx_type_selector` for selector stability and
/// `encode_execute_envelope` for ABI shape — and then synthesize a
/// `UserOperation` directly to confirm that a `DelegationScopeValidator`
/// gates it correctly. The synthesis test is the real assertion of the
/// architectural property: a typed Tenzro transaction can be projected
/// into an ERC-7579 execute envelope that the on-chain validator chain
/// understands.
#[cfg(test)]
mod aa_pre_sign_tests {
    use super::*;
    use std::sync::Arc;
    use std::time::{SystemTime, UNIX_EPOCH};
    use tenzro_vm::aa_delegation_validator::{
        DelegationScopeValidator, EnforcedScope, InMemoryScopeOracle,
    };
    use tenzro_vm::aa_validators::{
        IValidator, ModuleAttestation, ModuleType, NoOpValidator, ValidatorRegistry,
    };

    fn now_ts() -> u64 {
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.as_secs())
            .unwrap_or(0)
    }

    /// Build a fresh `ValidatorRegistry` with one `DelegationScopeValidator`
    /// installed for `sender`, gated by an in-memory `EnforcedScope`.
    fn install_for(
        sender: &[u8; 20],
        scope: EnforcedScope,
    ) -> (Arc<ValidatorRegistry>, [u8; 20]) {
        let module_addr = [0xDDu8; 20];
        let oracle = Arc::new(InMemoryScopeOracle::new());
        oracle.set(sender.to_vec(), scope);

        let inner: Arc<dyn IValidator> = Arc::new(NoOpValidator::new(module_addr));
        let validator: Arc<dyn IValidator> = Arc::new(DelegationScopeValidator::new(
            module_addr,
            inner,
            oracle,
        ));

        let registry = Arc::new(ValidatorRegistry::new());
        registry.attestations().attest(ModuleAttestation {
            module_address: module_addr,
            module_type: ModuleType::Validator,
            registry: *registry.trusted_registry(),
            attester: [0xAAu8; 20],
            attestation_data: b"audit-pass".to_vec(),
            revoked: false,
        });
        registry
            .install(
                sender.to_vec(),
                ModuleType::Validator,
                validator,
                100,
                Vec::new(),
            )
            .expect("install");
        (registry, module_addr)
    }

    fn make_user_op(sender: &[u8; 20], call_data: Vec<u8>) -> tenzro_vm::UserOperation {
        tenzro_vm::UserOperation {
            sender: sender.to_vec(),
            nonce: 0,
            factory: Vec::new(),
            factory_data: Vec::new(),
            call_data,
            call_gas_limit: 21_000,
            verification_gas_limit: 100_000,
            pre_verification_gas: 21_000,
            max_fee_per_gas: 1_000_000_000,
            max_priority_fee_per_gas: 1_000_000_000,
            paymaster: Vec::new(),
            paymaster_verification_gas_limit: 0,
            paymaster_post_op_gas_limit: 0,
            paymaster_data: Vec::new(),
            signature: vec![0xAAu8; 65],
        }
    }

    #[test]
    fn tx_type_selector_is_stable_per_variant() {
        let transfer_a = tx_type_selector(&TransactionType::Transfer { amount: 100 });
        let transfer_b = tx_type_selector(&TransactionType::Transfer { amount: 999 });
        // Selectors depend only on the variant name, not the field values.
        assert_eq!(transfer_a, transfer_b);

        let escrow = tx_type_selector(&TransactionType::RefundEscrow {
            escrow_id: [0u8; 32],
        });
        // Distinct variants produce distinct selectors.
        assert_ne!(transfer_a, escrow);
    }

    #[test]
    fn encode_execute_envelope_matches_standard_decoder() {
        use tenzro_vm::aa_delegation_validator::{CallIntentDecoder, StandardExecuteDecoder};

        let target = [0xAAu8; 20];
        let value = 1_000_000_000_000_000_000u128; // 1 TNZO in 18-dec base units
        let selector = tx_type_selector(&TransactionType::Transfer { amount: value });
        let envelope = encode_execute_envelope(target, value, &selector);

        // The validator's decoder must successfully round-trip the envelope.
        let decoder = StandardExecuteDecoder;
        let intent = decoder.decode(&envelope).expect("decoder accepts envelope");
        assert_eq!(intent.target, target);
        assert_eq!(intent.value, value);
        assert_eq!(intent.selector, Some(selector));
    }

    #[test]
    fn delegation_scope_validator_rejects_over_limit_intent() {
        // Per-tx ceiling 0.5 TNZO; submit 1 TNZO — must reject.
        let sender = [0xBBu8; 20];
        let target = [0xCCu8; 20];
        let value = 1_000_000_000_000_000_000u128;
        let transfer_selector = tx_type_selector(&TransactionType::Transfer { amount: value });

        let scope = EnforcedScope {
            max_per_tx: Some(500_000_000_000_000_000u128),
            max_per_day: None,
            allowed_selectors: vec![transfer_selector],
            allowed_targets: Vec::new(),
            valid_after: 0,
            valid_until: 0,
            window_start_ts: now_ts(),
            spent_in_window: 0,
            now_ts: now_ts(),
        };
        let (registry, _) = install_for(&sender, scope);

        let call_data = encode_execute_envelope(target, value, &transfer_selector);
        let op = make_user_op(&sender, call_data);
        let op_hash = [0u8; 32];

        let result = registry
            .validate_user_op(&op, &op_hash)
            .expect("registry call succeeds");
        assert!(
            result.is_failure(),
            "scope-violating intent (1 TNZO > 0.5 TNZO ceiling) must be rejected"
        );
    }

    #[test]
    fn delegation_scope_validator_accepts_in_scope_intent() {
        let sender = [0xBBu8; 20];
        let target = [0xCCu8; 20];
        let value = 100_000_000_000_000_000u128; // 0.1 TNZO — under ceiling
        let transfer_selector = tx_type_selector(&TransactionType::Transfer { amount: value });

        let scope = EnforcedScope {
            max_per_tx: Some(500_000_000_000_000_000u128),
            max_per_day: None,
            allowed_selectors: vec![transfer_selector],
            allowed_targets: Vec::new(),
            valid_after: 0,
            valid_until: 0,
            window_start_ts: now_ts(),
            spent_in_window: 0,
            now_ts: now_ts(),
        };
        let (registry, _) = install_for(&sender, scope);

        let call_data = encode_execute_envelope(target, value, &transfer_selector);
        let op = make_user_op(&sender, call_data);
        let op_hash = [0u8; 32];

        let result = registry
            .validate_user_op(&op, &op_hash)
            .expect("registry call succeeds");
        assert!(
            !result.is_failure(),
            "in-scope intent (0.1 TNZO < 0.5 TNZO ceiling) must pass"
        );
    }

    #[test]
    fn delegation_scope_validator_rejects_disallowed_selector() {
        // Scope only permits Transfer; submit a RefundEscrow intent.
        let sender = [0xBBu8; 20];
        let target = [0xCCu8; 20];
        let value = 0u128;
        let transfer_selector = tx_type_selector(&TransactionType::Transfer { amount: 0 });
        let escrow_selector = tx_type_selector(&TransactionType::RefundEscrow {
            escrow_id: [0u8; 32],
        });
        assert_ne!(transfer_selector, escrow_selector);

        let scope = EnforcedScope {
            max_per_tx: None,
            max_per_day: None,
            allowed_selectors: vec![transfer_selector],
            allowed_targets: Vec::new(),
            valid_after: 0,
            valid_until: 0,
            window_start_ts: now_ts(),
            spent_in_window: 0,
            now_ts: now_ts(),
        };
        let (registry, _) = install_for(&sender, scope);

        let call_data = encode_execute_envelope(target, value, &escrow_selector);
        let op = make_user_op(&sender, call_data);
        let op_hash = [0u8; 32];

        let result = registry
            .validate_user_op(&op, &op_hash)
            .expect("registry call succeeds");
        assert!(
            result.is_failure(),
            "out-of-allowlist selector must be rejected"
        );
    }
}
